import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { Client } from "@modelcontextprotocol/client";
import { StdioClientTransport } from "@modelcontextprotocol/client/stdio";

describe("MCP server — stale tools (no live RPC for isStale/quote, mocked check)", () => {
  it("lists 3 tools", async () => {
    const transport = new StdioClientTransport({
      command: "npx",
      args: ["tsx", "src/mcp/server.ts"],
      cwd: process.cwd(),
    });
    const client = new Client({ name: "test", version: "1.0.0" });
    await client.connect(transport);
    const { tools } = await client.listTools();
    const names = tools.map((t) => t.name).sort();
    assert.deepEqual(names, ["stale_check", "stale_isStale", "stale_quote"]);
    await client.close();
  });

  it("stale_isStale — pure, no RPC", async () => {
    const transport = new StdioClientTransport({
      command: "npx",
      args: ["tsx", "src/mcp/server.ts"],
      cwd: process.cwd(),
    });
    const client = new Client({ name: "test", version: "1.0.0" });
    await client.connect(transport);
    const now = Math.floor(Date.now() / 1000);
    const fresh = await client.callTool({
      name: "stale_isStale",
      arguments: { updatedAt: String(now - 10), nowSeconds: now, maxAgeSeconds: 60 },
    });
    const freshText = (fresh.content as any)[0].text as string;
    assert.match(freshText, /ALLOW/);
    const stale = await client.callTool({
      name: "stale_isStale",
      arguments: { updatedAt: String(now - 100), nowSeconds: now, maxAgeSeconds: 60 },
    });
    assert.match((stale.content as any)[0].text as string, /BLOCK/);
    await client.close();
  });

  it("stale_quote — price math, no RPC", async () => {
    const transport = new StdioClientTransport({
      command: "npx",
      args: ["tsx", "src/mcp/server.ts"],
      cwd: process.cwd(),
    });
    const client = new Client({ name: "test", version: "1.0.0" });
    await client.connect(transport);
    const r = await client.callTool({
      name: "stale_quote",
      arguments: { answer: "245377000000", decimals: 8, amountEth: 0.5 },
    });
    const text = (r.content as any)[0].text as string;
    const j = JSON.parse(text);
    assert.equal(j.priceUsd, 2453.77);
    assert.equal(j.quoteUsd, 1226.885);
    // bad answer → isError
    const bad = await client.callTool({
      name: "stale_quote",
      arguments: { answer: "0", decimals: 8 },
    });
    assert.equal((bad as any).isError, true);
    await client.close();
  });

  it("stale_check — unknown feed not allowlisted → BLOCK (no live RPC)", async () => {
    const transport = new StdioClientTransport({
      command: "npx",
      args: ["tsx", "src/mcp/server.ts"],
      cwd: process.cwd(),
    });
    const client = new Client({ name: "test", version: "1.0.0" });
    await client.connect(transport);
    const r = await client.callTool({
      name: "stale_check",
      arguments: {
        rpc: "https://ethereum-rpc.publicnode.com",
        feed: "0x0000000000000000000000000000000000000000",
        maxAgeSeconds: 60,
      },
    });
    const text = (r.content as any)[0].text as string;
    const j = JSON.parse(text);
    // unknown feed fails closed on the allowlist before any RPC call
    assert.equal(j.decision, "BLOCK");
    assert.equal(j.allowExecute, false);
    assert.match(j.reason, /unknown\/unsupported feed/);
    await client.close();
  });

  it("huge and malformed inputs — fail closed", async () => {
    const transport = new StdioClientTransport({
      command: "npx",
      args: ["tsx", "src/mcp/server.ts"],
      cwd: process.cwd(),
    });
    const client = new Client({ name: "test", version: "1.0.0" });
    await client.connect(transport);
    const now = Math.floor(Date.now() / 1000);
    // huge future timestamp via stale_isStale → BLOCK
    const huge = await client.callTool({
      name: "stale_isStale",
      arguments: {
        updatedAt: String((BigInt(1) << BigInt(40)).toString()),
        nowSeconds: now,
        maxAgeSeconds: 60,
      },
    });
    assert.match((huge.content as any)[0].text as string, /BLOCK/);
    // huge amountEth overflow via quote → isError
    const badQuote = await client.callTool({
      name: "stale_quote",
      arguments: { answer: "100000000000", decimals: 8, amountEth: Number.MAX_VALUE },
    });
    assert.equal((badQuote as any).isError, true);
    await client.close();
  });
});

import type { ChildProcess, IOType } from 'node:child_process';
import process from 'node:process';
import type { Stream } from 'node:stream';
import { PassThrough } from 'node:stream';

import type { JSONRPCMessage, Transport } from '@modelcontextprotocol/core-internal';
import { ReadBuffer, SdkError, SdkErrorCode, serializeMessage } from '@modelcontextprotocol/core-internal';
import spawn from 'cross-spawn';

export type StdioServerParameters = {
    /**
     * The executable to run to start the server.
     */
    command: string;

    /**
     * Command line arguments to pass to the executable.
     */
    args?: string[];

    /**
     * The environment to use when spawning the process.
     *
     * If not specified, the result of {@linkcode getDefaultEnvironment} will be used.
     */
    env?: Record<string, string>;

    /**
     * How to handle stderr of the child process. This matches the semantics of Node's `child_process.spawn`.
     *
     * The default is `"inherit"`, meaning messages to stderr will be printed to the parent process's stderr.
     */
    stderr?: IOType | Stream | number;

    /**
     * The working directory to use when spawning the process.
     *
     * If not specified, the current working directory will be inherited.
     */
    cwd?: string;

    /**
     * Maximum size of the read buffer in bytes. If a single message exceeds
     * this size the transport will emit an error and close.
     *
     * Defaults to 10 MB.
     */
    maxBufferSize?: number;
};

/**
 * Environment variables to inherit by default, if an environment is not explicitly given.
 */
export const DEFAULT_INHERITED_ENV_VARS =
    process.platform === 'win32'
        ? [
              'APPDATA',
              'HOMEDRIVE',
              'HOMEPATH',
              'LOCALAPPDATA',
              'PATH',
              'PROCESSOR_ARCHITECTURE',
              'SYSTEMDRIVE',
              'SYSTEMROOT',
              'TEMP',
              'USERNAME',
              'USERPROFILE',
              'PROGRAMFILES'
          ]
        : /* list inspired by the default env inheritance of sudo */
          ['HOME', 'LOGNAME', 'PATH', 'SHELL', 'TERM', 'USER'];

/**
 * Returns a default environment object including only environment variables deemed safe to inherit.
 */
export function getDefaultEnvironment(): Record<string, string> {
    const env: Record<string, string> = {};

    for (const key of DEFAULT_INHERITED_ENV_VARS) {
        const value = process.env[key];
        if (value === undefined) {
            continue;
        }

        if (value.startsWith('()')) {
            // Skip functions, which are a security risk.
            continue;
        }

        env[key] = value;
    }

    return env;
}

/**
 * Client transport for stdio: this will connect to a server by spawning a process and communicating with it over stdin/stdout.
 *
 * This transport is only available in Node.js environments.
 */
export class StdioClientTransport implements Transport {
    private _process?: ChildProcess;
    private _readBuffer: ReadBuffer;
    private _serverParams: StdioServerParameters;
    private _stderrStream: PassThrough | null = null;

    onclose?: () => void;
    onerror?: (error: Error) => void;
    onmessage?: (message: JSONRPCMessage) => void;

    constructor(server: StdioServerParameters) {
        this._serverParams = server;
        this._readBuffer = new ReadBuffer({ maxBufferSize: server.maxBufferSize });
        if (server.stderr === 'pipe' || server.stderr === 'overlapped') {
            this._stderrStream = new PassThrough();
        }
    }

    /**
     * Starts the server process and prepares to communicate with it.
     */
    async start(): Promise<void> {
        if (this._process) {
            throw new Error(
                'StdioClientTransport already started! If using Client class, note that connect() calls start() automatically.'
            );
        }

        return new Promise((resolve, reject) => {
            this._process = spawn(this._serverParams.command, this._serverParams.args ?? [], {
                // merge default env with server env because mcp server needs some env vars
                env: {
                    ...getDefaultEnvironment(),
                    ...this._serverParams.env
                },
                stdio: ['pipe', 'pipe', this._serverParams.stderr ?? 'inherit'],
                shell: false,
                windowsHide: process.platform === 'win32',
                cwd: this._serverParams.cwd
            });

            this._process.on('error', error => {
                reject(error);
                this.onerror?.(error);
            });

            this._process.on('spawn', () => {
                resolve();
            });

            this._process.on('close', _code => {
                this._process = undefined;
                this.onclose?.();
            });

            this._process.stdin?.on('error', error => {
                this.onerror?.(error);
            });

            this._process.stdout?.on('data', chunk => {
                try {
                    this._readBuffer.append(chunk);
                    this.processReadBuffer();
                } catch (error) {
                    this.onerror?.(error as Error);
                    this.close().catch(() => {});
                }
            });

            this._process.stdout?.on('error', error => {
                this.onerror?.(error);
            });

            if (this._stderrStream && this._process.stderr) {
                this._process.stderr.pipe(this._stderrStream);
            }
        });
    }

    /**
     * The `stderr` stream of the child process, if {@linkcode StdioServerParameters.stderr} was set to `"pipe"` or `"overlapped"`.
     *
     * If `stderr` piping was requested, a `PassThrough` stream is returned _immediately_, allowing callers to
     * attach listeners before the `start` method is invoked. This prevents loss of any early
     * error output emitted by the child process.
     */
    get stderr(): Stream | null {
        if (this._stderrStream) {
            return this._stderrStream;
        }

        return this._process?.stderr ?? null;
    }

    /**
     * The child process pid spawned by this transport.
     *
     * This is only available after the transport has been started.
     */
    get pid(): number | null {
        return this._process?.pid ?? null;
    }

    private processReadBuffer() {
        while (true) {
            try {
                const message = this._readBuffer.readMessage();
                if (message === null) {
                    break;
                }

                this.onmessage?.(message);
            } catch (error) {
                this.onerror?.(error as Error);
            }
        }
    }

    /**
     * Reap a disposable probe sibling (see the version-negotiation sibling
     * flow): signal-first teardown awaiting process `exit` — never the `close`
     * event, so a helper process holding the child's stdio pipes can never
     * block disposal. Not part of the public transport lifecycle.
     *
     * @internal
     */
    private async _dispose(): Promise<void> {
        const proc = this._process;
        this._process = undefined;
        if (proc && proc.exitCode === null && proc.signalCode === null) {
            const exited = new Promise<void>(resolve => proc.once('exit', () => resolve()));
            try {
                proc.stdin?.end();
            } catch {
                // ignore
            }
            try {
                proc.kill('SIGTERM');
            } catch {
                // ignore
            }
            await Promise.race([exited, new Promise(resolve => setTimeout(resolve, 1000).unref())]);
            if (proc.exitCode === null && proc.signalCode === null) {
                try {
                    proc.kill('SIGKILL');
                } catch {
                    // ignore
                }
            }
            await exited;
        }
        // The child is gone — release the PARENT-side pipe handles too. A helper
        // process holding the inherited write ends would otherwise keep them (and
        // with them the host's event loop: stdout carries a flowing 'data'
        // listener from start()) alive until the helper exits.
        try {
            proc?.stdout?.destroy();
        } catch {
            // ignore
        }
        try {
            proc?.stdin?.destroy();
        } catch {
            // ignore
        }
        try {
            proc?.stderr?.destroy();
        } catch {
            // ignore
        }
        this._readBuffer.clear();
    }

    async close(): Promise<void> {
        if (this._process) {
            const processToClose = this._process;
            this._process = undefined;

            const closePromise = new Promise<void>(resolve => {
                processToClose.once('close', () => {
                    resolve();
                });
            });

            try {
                processToClose.stdin?.end();
            } catch {
                // ignore
            }

            await Promise.race([closePromise, new Promise(resolve => setTimeout(resolve, 2000).unref())]);

            if (processToClose.exitCode === null) {
                try {
                    processToClose.kill('SIGTERM');
                } catch {
                    // ignore
                }

                await Promise.race([closePromise, new Promise(resolve => setTimeout(resolve, 2000).unref())]);
            }

            if (processToClose.exitCode === null) {
                try {
                    processToClose.kill('SIGKILL');
                } catch {
                    // ignore
                }
            }
        }

        this._readBuffer.clear();
    }

    send(message: JSONRPCMessage): Promise<void> {
        return new Promise(resolve => {
            if (!this._process?.stdin) {
                throw new SdkError(SdkErrorCode.NotConnected, 'Not connected');
            }

            const json = serializeMessage(message);
            if (this._process.stdin.write(json)) {
                resolve();
            } else {
                this._process.stdin.once('drain', resolve);
            }
        });
    }
}

