        GetTaskResultSchema,
        ListTasksResultSchema,
        CreateTaskResultSchema
    ]);

    const ServerRequestSchema = z.union([
        PingRequestSchema,
        CreateMessageRequestSchema,
        ElicitRequestSchema,
        ListRootsRequestSchema,
        GetTaskRequestSchema,
        GetTaskPayloadRequestSchema,
        ListTasksRequestSchema,
