        JSONObjectSchema,
        ProgressTokenSchema,
        CursorSchema,
        TaskMetadataSchema,
        RelatedTaskMetadataSchema,
        RequestMetaSchema,
        BaseRequestParamsSchema,
        TaskAugmentedRequestParamsSchema,
