import type * as z from 'zod/v4';

import type { NotificationMethod, NotificationTypeMap, RequestMethod, RequestTypeMap, ResultTypeMap } from '../../types/types';
import type { Rev2025WireSchemas } from './buildSchemas';
import { buildSchemas2025 } from './buildSchemas';

/* The era's wire vocabulary, derived from the wire role unions in
 * `./buildSchemas.ts` (the same unions the registries used to be built from
 * at runtime). Keying the maps by these derived unions makes drift a compile
 * error in BOTH directions: a union member without a map entry, a map entry
 * the unions do not know, and an entry pointing at a different method's
 * schema all fail to typecheck. */
type WireRequest = z.output<Rev2025WireSchemas['ClientRequestSchema']> | z.output<Rev2025WireSchemas['ServerRequestSchema']>;
type WireNotification = z.output<Rev2025WireSchemas['ClientNotificationSchema']> | z.output<Rev2025WireSchemas['ServerNotificationSchema']>;

/** Every request method in the 2025-era wire vocabulary (the typed `RequestMethod` surface plus the task family). */
export type Rev2025RequestMethod = WireRequest['method'];
/** Every notification method in the 2025-era wire vocabulary. */
export type Rev2025NotificationMethod = WireNotification['method'];

/**
 * The typed-method surface this era serves: the typed `RequestMethod` set
 * minus methods whose wire vocabulary does not exist on this era (e.g.
 * `server/discover`, which the typed maps carry but only the 2026-era
 * registry serves). Deriving the subset from the era's own wire role unions
 * keeps the both-direction drift guard: a typed 2025-era method without a map
 * entry, or a map entry the era's wire vocabulary does not know, is a compile
 * error.
 */
type Rev2025TypedRequestMethod = Extract<RequestMethod, Rev2025RequestMethod>;

/* Static method membership — the schema-free half of the registry.
 *
 * These null-valued objects carry ONLY the method keys, in the same order the
 * eager schema maps used to declare them (so the exported method lists stay
 * byte-identical to the pre-lazy builder). The mapped-type keying preserves
 * the both-direction drift guard: a union member without a key, or a key the
 * union does not know, is a compile error. Membership checks and the exported
 * lists read these objects and never touch the schema memo. */
const requestMethodKeys: { readonly [M in Rev2025RequestMethod]: null } = {
    ping: null,
    initialize: null,
    'completion/complete': null,
    'logging/setLevel': null,
    'prompts/get': null,
    'prompts/list': null,
    'resources/list': null,
    'resources/templates/list': null,
    'resources/read': null,
    'resources/subscribe': null,
    'resources/unsubscribe': null,
    'tools/call': null,
    'tools/list': null,
    'tasks/get': null,
    'tasks/result': null,
    'tasks/list': null,
    'tasks/cancel': null,
    'sampling/createMessage': null,
    'elicitation/create': null,
    'roots/list': null
};

const notificationMethodKeys: { readonly [M in Rev2025NotificationMethod]: null } = {
    'notifications/cancelled': null,
    'notifications/progress': null,
    'notifications/initialized': null,
    'notifications/roots/list_changed': null,
    'notifications/tasks/status': null,
    'notifications/message': null,
    'notifications/resources/updated': null,
    'notifications/resources/list_changed': null,
    'notifications/tools/list_changed': null,
    'notifications/prompts/list_changed': null,
    'notifications/elicitation/complete': null
};

const resultMethodKeys: { readonly [M in Rev2025TypedRequestMethod]: null } = {
    ping: null,
    initialize: null,
    'completion/complete': null,
    'logging/setLevel': null,
    'prompts/get': null,
    'prompts/list': null,
    'resources/list': null,
    'resources/templates/list': null,
    'resources/read': null,
    'resources/subscribe': null,
    'resources/unsubscribe': null,
    'tools/call': null,
    'tools/list': null,
    'sampling/createMessage': null,
    'elicitation/create': null,
    'roots/list': null
};

/* Lazy schema maps — built once, on the first schema lookup, from the era's
 * memoized schema factory. The entries are the SAME schema objects the wire
 * role unions are built from (reference identity is pinned by
 * `test/types/registryPins.test.ts`), and the key order preserves the
 * pre-split union iteration order. The mapped types below are unchanged from
 * the eager maps, so the drift guards still apply entry by entry. */
interface RegistryMaps {
    /* Runtime schema lookup — request and notification schemas by method. */
    readonly requestSchemas: { readonly [M in Rev2025RequestMethod]: z.ZodType<Extract<WireRequest, { method: M }>> };
    readonly notificationSchemas: { readonly [M in Rev2025NotificationMethod]: z.ZodType<Extract<WireNotification, { method: M }>> };
    /* Runtime schema lookup — result schemas by method.
     *
     * Keyed by the era's typed-method subset and valued by
     * `z.ZodType<ResultTypeMap[M]>` so the runtime map and the typed
     * `ResultTypeMap` cannot drift: a missing entry, an extra key, or an entry
     * that does not parse to the typed map's result type is a compile error. No
     * entry may be looser than the typed map (no task-result union members) and
     * no key may fall outside it (no `tasks/*` entries — the task methods are
     * 2025-11-25 wire vocabulary with no SDK runtime; callers needing task
     * interop pass an explicit schema). The `tools/call` entry is the wire-seam
     * wrapper `CallToolResultWireSchema` (content-default guard + tolerance),
     * which lives with the era schemas in `./buildSchemas.ts`. */
    readonly resultSchemas: { readonly [M in Rev2025TypedRequestMethod]: z.ZodType<ResultTypeMap[M]> };
}

let maps: RegistryMaps | undefined;

function registryMaps(): RegistryMaps {
    if (maps) return maps;
    const s = buildSchemas2025();
    maps = {
        requestSchemas: {
            ping: s.PingRequestSchema,
            initialize: s.InitializeRequestSchema,
            'completion/complete': s.CompleteRequestSchema,
            'logging/setLevel': s.SetLevelRequestSchema,
            'prompts/get': s.GetPromptRequestSchema,
            'prompts/list': s.ListPromptsRequestSchema,
            'resources/list': s.ListResourcesRequestSchema,
            'resources/templates/list': s.ListResourceTemplatesRequestSchema,
            'resources/read': s.ReadResourceRequestSchema,
            'resources/subscribe': s.SubscribeRequestSchema,
            'resources/unsubscribe': s.UnsubscribeRequestSchema,
            'tools/call': s.CallToolRequestSchema,
            'tools/list': s.ListToolsRequestSchema,
            'tasks/get': s.GetTaskRequestSchema,
            'tasks/result': s.GetTaskPayloadRequestSchema,
            'tasks/list': s.ListTasksRequestSchema,
            'tasks/cancel': s.CancelTaskRequestSchema,
            'sampling/createMessage': s.CreateMessageRequestSchema,
            'elicitation/create': s.ElicitRequestSchema,
            'roots/list': s.ListRootsRequestSchema
        },
        notificationSchemas: {
            'notifications/cancelled': s.CancelledNotificationSchema,
            'notifications/progress': s.ProgressNotificationSchema,
            'notifications/initialized': s.InitializedNotificationSchema,
            'notifications/roots/list_changed': s.RootsListChangedNotificationSchema,
            'notifications/tasks/status': s.TaskStatusNotificationSchema,
            'notifications/message': s.LoggingMessageNotificationSchema,
            'notifications/resources/updated': s.ResourceUpdatedNotificationSchema,
            'notifications/resources/list_changed': s.ResourceListChangedNotificationSchema,
            'notifications/tools/list_changed': s.ToolListChangedNotificationSchema,
            'notifications/prompts/list_changed': s.PromptListChangedNotificationSchema,
            'notifications/elicitation/complete': s.ElicitationCompleteNotificationSchema
        },
        resultSchemas: {
            ping: s.EmptyResultSchema,
            initialize: s.InitializeResultSchema,
            'completion/complete': s.CompleteResultSchema,
            'logging/setLevel': s.EmptyResultSchema,
            'prompts/get': s.GetPromptResultSchema,
            'prompts/list': s.ListPromptsResultSchema,
            'resources/list': s.ListResourcesResultSchema,
            'resources/templates/list': s.ListResourceTemplatesResultSchema,
            'resources/read': s.ReadResourceResultSchema,
            'resources/subscribe': s.EmptyResultSchema,
            'resources/unsubscribe': s.EmptyResultSchema,
            'tools/call': s.CallToolResultWireSchema,
            'tools/list': s.ListToolsResultSchema,
            'sampling/createMessage': s.CreateMessageResultWithToolsSchema,
            'elicitation/create': s.ElicitResultSchema,
            'roots/list': s.ListRootsResultSchema
        }
    };
    return maps;
}

/**
 * Forces the lazy registry maps (and, through them, the era's schema memo).
 * Warm-up hook for `preloadSchemas()` — no-op once the maps exist.
 */
export function warmRegistryMaps2025(): void {
    registryMaps();
}

/** The 2025-era request-method set (registry membership = the deletion story). */
export function hasRequestMethod2025(method: string): method is Rev2025RequestMethod {
    return Object.prototype.hasOwnProperty.call(requestMethodKeys, method);
}

/** The 2025-era notification-method set. */
export function hasNotificationMethod2025(method: string): method is Rev2025NotificationMethod {
    return Object.prototype.hasOwnProperty.call(notificationMethodKeys, method);
}

/** Result-map membership: exactly the era's typed-method subset (no task entries, no 2026-only methods). */
function hasResultMethod(method: string): method is Rev2025TypedRequestMethod {
    return Object.prototype.hasOwnProperty.call(resultMethodKeys, method);
}

/**
 * Gets the Zod schema for validating results of a given request method.
 * Returns `undefined` for non-spec methods and 2026-only methods.
 * The typed overload is backed by the map's own typing (`z.ZodType<ResultTypeMap[M]>`
 * per entry), so callers with a statically known 2025-era method can use the
 * parsed value without a type assertion.
 */
export function getResultSchema<M extends Rev2025TypedRequestMethod>(method: M): z.ZodType<ResultTypeMap[M]>;
export function getResultSchema(method: string): z.ZodType | undefined;
export function getResultSchema(method: string): z.ZodType | undefined {
    return hasResultMethod(method) ? registryMaps().resultSchemas[method] : undefined;
}

/**
 * Gets the Zod schema for a given request method.
 * Returns `undefined` for non-spec methods and 2026-only methods.
 * The typed overload returns a ZodType that parses to `RequestTypeMap[M]`,
 * allowing callers to use `schema.parse()` without additional type assertions.
 */
export function getRequestSchema<M extends Rev2025TypedRequestMethod>(method: M): z.ZodType<RequestTypeMap[M]>;
export function getRequestSchema(method: string): z.ZodType | undefined;
export function getRequestSchema(method: string): z.ZodType | undefined {
    return hasRequestMethod2025(method) ? registryMaps().requestSchemas[method] : undefined;
}

/**
 * Gets the Zod schema for a given notification method.
 * Returns `undefined` for non-spec methods.
 * @see getRequestSchema for the typed-overload contract.
 */
export function getNotificationSchema<M extends NotificationMethod>(method: M): z.ZodType<NotificationTypeMap[M]>;
export function getNotificationSchema(method: string): z.ZodType | undefined;
export function getNotificationSchema(method: string): z.ZodType | undefined {
    return hasNotificationMethod2025(method) ? registryMaps().notificationSchemas[method] : undefined;
}

/** Registry method lists (for the spec-method universe and the CI registry-diff oracle). */
export const rev2025RequestMethods: readonly string[] = Object.keys(requestMethodKeys);
export const rev2025NotificationMethods: readonly string[] = Object.keys(notificationMethodKeys);
/**
 * The 2025-era wire codec: decode/encode ≈ identity.
 *
 * This codec serves every legacy protocol version (2024-10-07 … 2025-11-25).
 * It is BEHAVIOR-FROZEN behind the Q10-L2 byte-identity suite — its schemas
 * are today's schemas, its registry is today's method map, and its encode
 * path is the identity.
 *
 * Never-stamp guarantee: this module NEVER WRITES 2026 vocabulary
 * (`resultType`, `ttlMs`, `cacheScope`, the `_meta` envelope keys) — there is
 * no code path that can. `encodeResult` is the identity for every result
 * EXCEPT the SEP-2106 `tools/list` projection: when a tool's neutral
 * `outputSchema` has a non-object root, the 2025 wire shape requires
 * `type:'object'` there, so the codec PROJECTS the public superset down by
 * wrapping the advertised schema as `{type:'object',
 * properties:{result:<natural>}, required:['result']}`. That projection
 * narrows neutral→2025-wire; it never adds 2026 vocabulary.
 *
 * One deliberate exception to "no 2026 code path" (Q1-SD3 ii, amending the
 * V-2 'no code path at all' design claim): `decodeResult` STRIPS a foreign
 * `resultType` key from inbound results before validation (strip-on-lift).
 * `resultType` is not 2025 vocabulary — a 2025 peer that sends it is
 * misbehaving — and the ruled posture is tolerate-and-drop so the foreign key
 * can neither surface to consumers (the neutral types have no slot for it)
 * nor leak through the retained loose-object passthrough. This is the ONLY
 * 2026-vocabulary code path in the 2025 codec, it exists on the decode side
 * only, and it deletes — never reads, maps, or emits — the foreign value.
 */
import type * as z from 'zod/v4';

import type { CallToolResult, Result } from '../../types/types';
import type { DecodedResult, EnvelopeIssue, LiftedWireMaterial, OutboundEnvelopeMaterial, ValidateOutcome, WireCodec } from '../codec';
import { appendTextFallbackForNonObject } from '../textFallback';
import { buildSchemas2025 } from './buildSchemas';
import { isNonObjectJsonSchemaRoot, wrapOutputSchemaForLegacy } from './legacyWrap';
import { getNotificationSchema, getRequestSchema, getResultSchema, hasNotificationMethod2025, hasRequestMethod2025 } from './registry';

function isPlainObject(value: unknown): value is Record<string, unknown> {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/** Tri-state wrap of an optional Zod schema lookup (the function-only contract). */
function triState<T>(schema: z.ZodType<T> | undefined, raw: unknown): ValidateOutcome<T> {
    if (schema === undefined) return { ok: false, reason: 'not-in-era' };
    const parsed = schema.safeParse(raw);
    return parsed.success ? { ok: true, value: parsed.data } : { ok: false, reason: 'invalid', message: String(parsed.error) };
}

const NOT_IN_ERA: ValidateOutcome<never> = { ok: false, reason: 'not-in-era' };

/** Whether a `tools/list` entry advertises a non-object `outputSchema` root that needs the SEP-2106 legacy wrap. */
function toolNeedsLegacyWrap(t: unknown): t is { outputSchema: Record<string, unknown> } {
    return isPlainObject(t) && isPlainObject(t['outputSchema']) && isNonObjectJsonSchemaRoot(t['outputSchema']);
}

/** The wire→neutral trust boundary: a decoded 2025-era wire result is adopted as the neutral `Result` here (the module's single deliberate assertion). */
function toNeutralResult(value: unknown): Result {
    return value as Result;
}

export const rev2025Codec: WireCodec = {
    era: '2025-11-25',

    hasRequestMethod: hasRequestMethod2025,
    hasNotificationMethod: hasNotificationMethod2025,

    // ── Function-only validation surface ──
    validateRequest: (method: string, raw: unknown) => triState(getRequestSchema(method), raw),
    validateResult: (method: string, raw: unknown) => triState(getResultSchema(method), raw),
    validateNotification: (method: string, raw: unknown) => triState(getNotificationSchema(method), raw),
    // No in-band input-request vocabulary on this era: elicitation, sampling
    // and roots are real wire request methods here (see the registry).
    hasInputRequestMethod: (): boolean => false,
    validateInputRequest: (): ValidateOutcome<never> => NOT_IN_ERA,
    validateInputResponse: (): ValidateOutcome<never> => NOT_IN_ERA,

    // Arrow literals can't carry overload signatures; the cast is sound (the
    // boolean dispatches to exactly the schema each overload names). The
    // schemas are pulled through the era's memo so the codec module itself
    // stays construction-free at import time.
    samplingResultVariant: ((hasTools: boolean, raw: unknown) => {
        const s = buildSchemas2025();
        return triState(hasTools ? s.CreateMessageResultWithToolsSchema : s.CreateMessageResultSchema, raw);
    }) as WireCodec['samplingResultVariant'],

    // The 2025 era carries no per-request `_meta` envelope — legacy wire
    // bytes stay identical (the never-stamp guarantee, outbound-request half).
    outboundEnvelope: (_material: OutboundEnvelopeMaterial): undefined => undefined,
    validateEnvelopeMeta: (_meta: Readonly<Record<string, unknown>>): EnvelopeIssue[] => [],

    projectCallToolResult(result: CallToolResult, advertisedOutputSchema): CallToolResult {
        // Era-agnostic SEP-2106 §4.3 TextContent auto-append first (value-shape-based).
        const withText = appendTextFallbackForNonObject(result);
        const sc = withText.structuredContent;
        if (sc === undefined) return withText;
        // SEP-2106 result-side projection. Wrap as `{result:<sc>}` when EITHER:
        //  - the value is non-object (array/primitive/`null`) — REGARDLESS of
        //    advertised schema, because the 2025 wire shape requires
        //    `structuredContent` to be an object (a schema-less tool returning
        //    `[1,2,3]` would otherwise ship wire-illegal bytes), or
        //  - the advertised `outputSchema` has a non-object root — so the
        //    result satisfies the wrapped schema this codec's
        //    `encodeResult('tools/list', …)` advertised for the same tool.
        const valueIsNonObject = typeof sc !== 'object' || sc === null || Array.isArray(sc);
        const schemaWrapped = advertisedOutputSchema !== undefined && isNonObjectJsonSchemaRoot(advertisedOutputSchema);
        if (!valueIsNonObject && !schemaWrapped) return withText;
        return { ...withText, structuredContent: { result: sc } };
    },

    decodeResult(_method: string, raw: unknown): DecodedResult {
        // Strip-on-lift (Q1-SD3 ii): a foreign `resultType` on the 2025 leg is
        // dropped before validation, whatever its value. Validation judges the
        // husk — the registry wire-seam schema on the plain path, the caller's
        // schema on the explicit path (task interop).
        if (isPlainObject(raw) && 'resultType' in raw) {
            const stripped = { ...raw };
            delete stripped['resultType'];
            return { kind: 'complete', result: toNeutralResult(stripped) };
        }
        return { kind: 'complete', result: toNeutralResult(raw) };
    },

    // The never-stamp guarantee: never writes 2026 vocabulary. Identity for
    // every result EXCEPT the SEP-2106 `tools/list` projection (see header).
    // Copy-on-write: a listing with no non-object outputSchema roots returns
    // the same reference (the byte-identity suite pins this).
    encodeResult(method: string, result: Result): Result {
        if (method !== 'tools/list') return result;
        const tools = (result as { tools?: unknown }).tools;
        if (!Array.isArray(tools) || !tools.some(t => toolNeedsLegacyWrap(t))) return result;
        return {
            ...result,
            tools: tools.map(t => (toolNeedsLegacyWrap(t) ? { ...t, outputSchema: wrapOutputSchemaForLegacy(t.outputSchema) } : t))
        } as Result;
    },

    // The −32002 resource-not-found domain code maps to −32602 on the wire on
    // this era too (matching what the deployed v1.x SDK already emits — this
    // is not a behavior change for v1.x peers). There is deliberately no era
    // branch that preserves −32002.
    encodeErrorCode: (code: number): number => (code === -32_002 ? -32_602 : code),

    // The 2025 era never requires a per-request envelope.
    checkInboundEnvelope: (_material: LiftedWireMaterial): string | undefined => undefined
};
/**
 * 2026-era wire schemas (protocol revision 2026-07-28).
 *
 * Fully self-contained — no runtime imports from types/schemas.ts. The
 * neutral types/schemas.ts layer is the public-API superset and is free to
 * evolve; this file is the 2026 wire-parse contract and is BEHAVIOR-FROZEN
 * against the 2026-07-28 anchor. Every era-shared building block (content
 * blocks, resources, prompts, capabilities, notifications, …) that the wire
 * shapes compose is a frozen LOCAL copy — verbatim from the neutral layer at
 * the point this revision was sealed, dependencies first. The only cross-layer
 * dependency is `import type { JSONObject, JSONValue }` from the neutral types
 * barrel — pure structural type aliases with no parse behavior.
 *
 * This module is the only place the per-request `_meta` envelope is modeled.
 * The envelope is wire-only vocabulary: the protocol layer lifts it off
 * inbound requests before any handler runs and surfaces it at
 * `ctx.mcpReq.envelope`; the 2026-era codec enforces its requiredness at
 * dispatch time (`checkInboundEnvelope`) - the former neutral-schema JSDoc
 * deferral ("enforced per request at dispatch time, not here") is now
 * discharged by that codec step.
 *
 * No 2025-era traffic ever touches this module, so requiredness here is
 * bare and spec-exact (the shared-schema `.catch` hazards do not apply).
 *
 * SPEC-CURRENCY RE-SEAL (2026-07-17): the 2026-07-28 revision was re-sealed
 * upstream by spec PR #3002 (commit 71e30695, merged 2026-07-15 — after the
 * previous anchor pin f68d864a): the envelope's `clientInfo` demoted from
 * required to SHOULD, and `DiscoverResult.serverInfo` moved from the result
 * body to the new `ResultMetaObject` key
 * `_meta['io.modelcontextprotocol/serverInfo']` (optional on every result).
 * The shapes below are the re-sealed anchor, exactly — no pre-#3002 shape is
 * modeled anywhere (per ruling: the final revision is the only 2026-07-28).
 */
import * as z from 'zod/v4';

import {
    CLIENT_CAPABILITIES_META_KEY,
    CLIENT_INFO_META_KEY,
    LOG_LEVEL_META_KEY,
    PROTOCOL_VERSION_META_KEY,
    SERVER_INFO_META_KEY
} from '../../types/constants';
import type { JSONObject, JSONValue } from '../../types/types';

/**
 * The 2026-era request-method set — the hand-registry seed (see registry.ts
 * for the seed decisions). The dispatch maps below are mapped types over this
 * union, so a missing entry, an extra entry, or an entry pointing at another
 * method's schema is a compile error; the CI registry-diff oracle pins the
 * same set against the anchor at runtime.
 */
export type Rev2026RequestMethod =
    | 'tools/call'
    | 'tools/list'
    | 'prompts/get'
    | 'prompts/list'
    | 'resources/list'
    | 'resources/templates/list'
    | 'resources/read'
    | 'completion/complete'
    | 'server/discover'
    | 'subscriptions/listen';

/** The 2026-era notification-method set (the hand-registry seed; see the deletion list above). */
export type Rev2026NotificationMethod =
    | 'notifications/cancelled'
    | 'notifications/progress'
    | 'notifications/message'
    | 'notifications/resources/updated'
    | 'notifications/resources/list_changed'
    | 'notifications/tools/list_changed'
    | 'notifications/prompts/list_changed'
    | 'notifications/subscriptions/acknowledged';

function build() {
    /* ════════════════════════════════════════════════════════════════════════════
     * Frozen neutral-layer building blocks
     *
     * Everything from this point until the next ═-banner is a verbatim frozen
     * copy of a schema that, at the time this revision was sealed, lived in the
     * neutral types/schemas.ts. They are copied dependencies-first so no forward
     * references exist. They are NOT re-derived from the public layer at runtime —
     * a widening or tightening landed on types/schemas.ts has no effect here until
     * a deliberate per-revision re-freeze.
     * ════════════════════════════════════════════════════════════════════════════ */

    const JSONValueSchema: z.ZodType<JSONValue, JSONValue> = z.lazy(() =>
        z.union([z.string(), z.number(), z.boolean(), z.null(), z.record(z.string(), JSONValueSchema), z.array(JSONValueSchema)])
    );
    const JSONObjectSchema: z.ZodType<JSONObject, JSONObject> = z.record(z.string(), JSONValueSchema);

    /**
     * A progress token, used to associate progress notifications with the original request.
     */
    const ProgressTokenSchema = z.union([z.string(), z.number().int()]);

    /**
     * An opaque token used to represent a cursor for pagination.
     */
    const CursorSchema = z.string();

    /**
     * A uniquely identifying ID for a request in JSON-RPC.
     */
    const RequestIdSchema = z.union([z.string(), z.number().int()]);

    /**
     * The sender or recipient of messages and data in a conversation.
     */
    const RoleSchema = z.enum(['user', 'assistant']);

    /**
     * The severity of a log message.
     */
    const LoggingLevelSchema = z.enum(['debug', 'info', 'notice', 'warning', 'error', 'critical', 'alert', 'emergency']);

    /**
     * A Zod schema for validating Base64 strings that is more performant and
     * robust for very large inputs than the default regex-based check. It avoids
     * stack overflows by using the native `atob` function for validation.
     */
    const Base64Schema = z.string().refine(
        val => {
            try {
                atob(val);
                return true;
            } catch {
                return false;
            }
        },
        { message: 'Invalid Base64 string' }
    );

    /* ─── Request/notification meta and base params ─── */

    /** @deprecated 2025-11-25 wire vocabulary with no SDK runtime; kept importable for interoperability only. */
    const TaskMetadataSchema = z.object({
        ttl: z.number().optional()
    });

    /** @deprecated 2025-11-25 wire vocabulary with no SDK runtime; kept importable for interoperability only. */
    const RelatedTaskMetadataSchema = z.object({
        taskId: z.string()
    });

    const RequestMetaSchema = z.looseObject({
        /**
         * If specified, the caller is requesting out-of-band progress notifications for this request (as represented by notifications/progress). The value of this parameter is an opaque token that will be attached to any subsequent notifications. The receiver is not obligated to provide these notifications.
         */
        progressToken: ProgressTokenSchema.optional(),
        /**
         * If specified, this request is related to the provided task.
         */
        'io.modelcontextprotocol/related-task': RelatedTaskMetadataSchema.optional()
    });

    const BaseRequestParamsSchema = z.object({
        _meta: RequestMetaSchema.optional()
    });

    /** @deprecated 2025-11-25 wire vocabulary with no SDK runtime; kept importable for interoperability only. */
    const TaskAugmentedRequestParamsSchema = BaseRequestParamsSchema.extend({
        task: TaskMetadataSchema.optional()
    });

    const NotificationsParamsSchema = z.object({
        _meta: RequestMetaSchema.optional()
    });

    const NotificationSchema = z.object({
        method: z.string(),
        params: NotificationsParamsSchema.loose().optional()
    });

    /* ─── Icons / base metadata / implementation ─── */

    const IconSchema = z.object({
        src: z.string(),
        mimeType: z.string().optional(),
        sizes: z.array(z.string()).optional(),
        theme: z.enum(['light', 'dark']).optional()
    });

    const IconsSchema = z.object({
        icons: z.array(IconSchema).optional()
    });

    const BaseMetadataSchema = z.object({
        name: z.string(),
        title: z.string().optional()
    });

    const ImplementationSchema = BaseMetadataSchema.extend({
        ...BaseMetadataSchema.shape,
        ...IconsSchema.shape,
        version: z.string(),
        websiteUrl: z.string().optional(),
