        JSONObjectSchema,
        ProgressTokenSchema,
        CursorSchema,
        RequestIdSchema,
        RoleSchema,
        LoggingLevelSchema,
        TaskMetadataSchema,
        RelatedTaskMetadataSchema,
        RequestMetaSchema,
        BaseRequestParamsSchema,
        TaskAugmentedRequestParamsSchema,
