/**
 * Protocol errors are JSON-RPC errors that cross the wire as error responses.
 * They use numeric error codes from the {@linkcode ProtocolErrorCode} enum.
 *
 * `instanceof` on this class (and its subclasses) is brand-matched, so it works
 * across separately bundled copies of the SDK — e.g. an error constructed by
 * `@modelcontextprotocol/client` matches the class re-exported by
 * `@modelcontextprotocol/server` in the same process.
 */
export class ProtocolError extends Error {
    static {
        Object.defineProperty(this, 'mcpBrand', { value: 'mcp.ProtocolError' });
    }

    static override [Symbol.hasInstance](value: unknown): boolean {
        return brandedHasInstance(this, value);
    }

    /**
     * Brand-based type guard: equivalent to `value instanceof this`, as an
     * explicit static predicate (the axios/AWS-SDK `isInstance` style). Reads
     * the caller's own brand via `this`, so every branded subclass gets a
     * correctly-scoped guard by inheritance. Must be invoked on the class —
     * in callback position write `v => SdkError.isInstance(v)`, not
     * `.filter(SdkError.isInstance)` (detached calls throw rather than
     * silently matching nothing).
     */
    static isInstance<T extends abstract new (...args: never[]) => unknown>(this: T, value: unknown): value is InstanceType<T> {
        if (typeof this !== 'function') {
            throw new TypeError(
                'isInstance must be called on the class (e.g. `SdkError.isInstance(value)`); for callbacks use `v => SdkError.isInstance(v)`'
            );
        }
        return brandedHasInstance(this, value);
    }

    constructor(
        public readonly code: number,
        message: string,
        public readonly data?: unknown
    ) {
        super(message);
        this.name = 'ProtocolError';
        stampErrorBrands(this, new.target);
    }

    /**
     * Factory method to create the appropriate error type based on the error code and data
     */
    static fromError(code: number, message: string, data?: unknown): ProtocolError {
        // Check for specific error types
        if (code === ProtocolErrorCode.UrlElicitationRequired && data) {
            const errorData = data as { elicitations?: unknown[] };
            if (errorData.elicitations) {
                return new UrlElicitationRequiredError(errorData.elicitations as ElicitRequestURLParams[], message);
            }
        }

        if (code === ProtocolErrorCode.UnsupportedProtocolVersion && data) {
            const errorData = data as Partial<UnsupportedProtocolVersionErrorData>;
            if (Array.isArray(errorData.supported) && typeof errorData.requested === 'string') {
                return new UnsupportedProtocolVersionError({ supported: errorData.supported, requested: errorData.requested }, message);
            }
        }

        // Resource not found is recognised on BOTH the spec-mandated −32602 and
        // the legacy −32002 (the spec's "clients SHOULD also accept −32002"
        // backwards-compatibility clause). On −32602 the data-shape parse is
        // narrowed to "exactly `{ uri: string }` and nothing else": a server's
        // own Invalid Params that happens to carry `data.uri` alongside other
        // keys (e.g. `{ uri, reason: 'uri must be https' }`) stays a generic
        // ProtocolError. On −32002 the code itself is the discriminator, so any
        // `data.uri` string suffices.
        if (code === ProtocolErrorCode.InvalidParams || code === ProtocolErrorCode.ResourceNotFound) {
            const errorData = data as Record<string, unknown> | undefined;
            if (
                typeof errorData?.uri === 'string' &&
                (code === ProtocolErrorCode.ResourceNotFound || Object.keys(errorData).length === 1)
            ) {
                return new ResourceNotFoundError(errorData.uri, message);
            }
        }

        if (code === ProtocolErrorCode.MissingRequiredClientCapability && data) {
            const errorData = data as Partial<MissingRequiredClientCapabilityErrorData>;
            if (
                errorData.requiredCapabilities !== null &&
                typeof errorData.requiredCapabilities === 'object' &&
                !Array.isArray(errorData.requiredCapabilities)
            ) {
                return new MissingRequiredClientCapabilityError({ requiredCapabilities: errorData.requiredCapabilities }, message);
            }
        }

        // Default to generic ProtocolError
        return new ProtocolError(code, message, data);
    }
}

/**
 * Error type for a `resources/read` miss: the requested resource does not
 * exist. The wire code is `-32602` (Invalid Params) on every protocol
 * revision — the spec MUST for revision 2026-07-28, and the value the v1.x
 * SDK has always emitted on earlier revisions. The error data echoes the
 * requested URI.
 *
 * Recognise this error by checking `error.data` is exactly `{ uri: string }`
 * (a `-32602` whose data carries `uri` and nothing else is resource-not-found;
 * any other `-32602` is an ordinary Invalid Params). For backwards compatibility, clients should also
 * accept `-32002` as resource not found — earlier SDK builds emitted that
 * code, and {@linkcode ProtocolError.fromError} reconstructs this class for
 * either code **when `error.data` carries `uri`** (a bare `-32002` without
 * `data.uri` stays a generic {@linkcode ProtocolError}). `instanceof` checks
 * are brand-matched and work across separately bundled copies of the SDK.
 */
export class ResourceNotFoundError extends ProtocolError {
    static {
        Object.defineProperty(this, 'mcpBrand', { value: 'mcp.ResourceNotFoundError' });
    }

    constructor(uri: string, message: string = `Resource not found: ${uri}`) {
        super(ProtocolErrorCode.InvalidParams, message, { uri });
    }

    /** The URI that was requested and not found. */
    get uri(): string {
        return (this.data as { uri: string }).uri;
    }
}

/**
 * Specialized error type when a tool requires a URL mode elicitation.
 * This makes it nicer for the client to handle since there is specific data to work with instead of just a code to check against.
 */
export class UrlElicitationRequiredError extends ProtocolError {
    static {
        Object.defineProperty(this, 'mcpBrand', { value: 'mcp.UrlElicitationRequiredError' });
    }

    constructor(elicitations: ElicitRequestURLParams[], message: string = `URL elicitation${elicitations.length > 1 ? 's' : ''} required`) {
        super(ProtocolErrorCode.UrlElicitationRequired, message, {
            elicitations: elicitations
        });
    }

    get elicitations(): ElicitRequestURLParams[] {
        return (this.data as { elicitations: ElicitRequestURLParams[] })?.elicitations ?? [];
    }
}

/**
 * Error type for the `-32022` UnsupportedProtocolVersion protocol error (protocol
 * revision 2026-07-28): the request's protocol version is unknown to the server or
 * unsupported by it.
 *
 * The error data lists the protocol versions the receiver supports (`supported`),
 * so the sender can choose a mutually supported version and retry, and echoes the
 * version that was requested (`requested`).
 */
export class UnsupportedProtocolVersionError extends ProtocolError {
    static {
        Object.defineProperty(this, 'mcpBrand', { value: 'mcp.UnsupportedProtocolVersionError' });
    }

    constructor(data: UnsupportedProtocolVersionErrorData, message: string = `Unsupported protocol version: ${data.requested}`) {
        super(ProtocolErrorCode.UnsupportedProtocolVersion, message, data);
    }

    /**
     * Protocol versions the receiver supports.
     */
    get supported(): string[] {
        return (this.data as UnsupportedProtocolVersionErrorData).supported;
    }

    /**
     * The protocol version that was requested.
     */
    get requested(): string {
        return (this.data as UnsupportedProtocolVersionErrorData).requested;
    }
}

/**
 * Error type for the `-32021` MissingRequiredClientCapability protocol error
 * (protocol revision 2026-07-28): processing the request requires a capability
 * the client did not declare in the request's `clientCapabilities`.
 *
 * The error data lists the missing capabilities (`requiredCapabilities`) in
 * the `ClientCapabilities` shape, so the client can see exactly what it would
 * have to declare for the request to be served. On HTTP, the response status
 * is `400 Bad Request`.
 *
 * Recognize this error by its code and `data.requiredCapabilities`, or by
 * `instanceof` — checks are brand-matched and work across separately bundled
 * copies of the SDK.
 */
export class MissingRequiredClientCapabilityError extends ProtocolError {
    static {
        Object.defineProperty(this, 'mcpBrand', { value: 'mcp.MissingRequiredClientCapabilityError' });
    }

    constructor(
        data: MissingRequiredClientCapabilityErrorData,
        message: string = `Missing required client capabilities: ${Object.keys(data.requiredCapabilities).join(', ')}`
    ) {
        super(ProtocolErrorCode.MissingRequiredClientCapability, message, data);
    }

    /**
     * The capabilities the server requires from the client to process the
     * request (only the missing capabilities are listed).
     */
    get requiredCapabilities(): ClientCapabilities {
        return (this.data as MissingRequiredClientCapabilityErrorData).requiredCapabilities;
    }
}
/**
 * The outbound result encode contract for the 2026-07-28 wire codec, as pure,
 * individually-testable steps. `encodeResult` applies them in order:
 *
 *  1. {@linkcode stampResultType} — the `resultType` discriminator. The SDK
 *     stamps `'complete'`; a handler-provided value passes through only for
 *     methods whose spec result vocabulary goes beyond `'complete'` (the
 *     multi round-trip request methods, whose results may be
 *     `input_required`). A non-`'complete'` value returned by a handler for
 *     any other method is a server bug and fails loudly (internal error)
 *     rather than being mis-typed on the wire.
 *  2. {@linkcode fillCacheFields} — the required `ttlMs`/`cacheScope` fields
 *     on cacheable results (SEP-2549), filled only when the post-stamp
 *     `resultType` is `'complete'` and the method is one of the cacheable
 *     operations. Resolution is most-specific-author-first: valid
 *     handler-returned values, then the configured cache hint attached by the
 *     server layer, then the conservative defaults
 *     `{ ttlMs: 0, cacheScope: 'private' }`. Invalid handler-returned values
 *     never reach the wire — they fall through to the next author.
 *  3. {@linkcode stampServerInfoMeta} — the `_meta` serverInfo key on every
 *     result (spec PR #3002: servers SHOULD identify themselves on every
 *     response). A handler-authored value wins; without a supplied identity
 *     the step is the identity function.
 *
 * Ordering matters and is pinned by tests: the stamp runs before the fill, so
 * an `input_required` result is never given cache fields.
 */
import type { CacheHint } from '../../shared/resultCacheHints';
import {
    cacheHintFallbackOf,
    isCacheableResultMethod,
    isValidCacheScope,
    isValidCacheTtlMs,
    RESULT_CACHE_HINT_FALLBACK
} from '../../shared/resultCacheHints';
import { SERVER_INFO_META_KEY } from '../../types/constants';
import { ProtocolErrorCode } from '../../types/enums';
import { ProtocolError } from '../../types/errors';
import type { Implementation, Result } from '../../types/types';

/** The default cache policy when neither the handler nor configuration provides one. */
export const DEFAULT_CACHE_TTL_MS = 0;
export const DEFAULT_CACHE_SCOPE = 'private';

/**
 * Request methods whose spec result vocabulary goes beyond `'complete'` on the
 * 2026-07-28 revision: their results may be `input_required` (multi
 * round-trip requests), so a handler-provided `resultType` passes through the
 * stamp untouched. `subscriptions/listen` is NOT in this set: it never emits
 * a JSON-RPC result — termination is stream close (HTTP) or
 * `notifications/cancelled` (stdio) per the spec.
 */
export const EXTENDED_RESULT_TYPE_METHODS: readonly string[] = ['tools/call', 'prompts/get', 'resources/read'];

/**
 * Step 1 of the encode contract: ensure the outbound result carries the
 * required `resultType` discriminator.
 *
 * - No handler-provided value → stamp `'complete'`.
 * - Handler-provided `'complete'` → kept as-is.
 * - Handler-provided non-`'complete'` value on a method whose vocabulary
 *   allows it ({@linkcode EXTENDED_RESULT_TYPE_METHODS}) → passes through.
 *   The value is forwarded verbatim — the wire vocabulary is an open union and
 *   the SDK does not validate the string, so emitting a `resultType` the
 *   negotiated revision does not define is the handler author's
 *   responsibility.
 * - Handler-provided non-`'complete'` value on any other method → internal
 *   error (loud): the value would be mis-typed on the wire, and silently
 *   rewriting it would hide a server bug.
 */
export function stampResultType(method: string, result: Result): Result {
    const provided = (result as Record<string, unknown>)['resultType'];
    if (provided === undefined) {
        return { ...result, resultType: 'complete' } as Result;
    }
    if (provided === 'complete') {
        return result;
    }
    if (EXTENDED_RESULT_TYPE_METHODS.includes(method)) {
        return result;
    }
    throw new ProtocolError(
        ProtocolErrorCode.InternalError,
        `Handler for ${method} returned resultType '${String(provided)}', but results of ${method} only support 'complete' on protocol revision 2026-07-28`
    );
}

/**
 * Step 2 of the encode contract: fill the required `ttlMs`/`cacheScope` fields
 * on cacheable results.
 *
 * Applies only when the (post-stamp) `resultType` is `'complete'` and the
 * method is one of the cacheable operations; everything else is returned
 * untouched apart from removing the configured-hint carrier. Field resolution
 * is per field, most specific author first: a valid handler-returned value,
 * then the configured cache hint attached by the server layer, then the
 * defaults. Handler-returned values are validated at encode time (`ttlMs`
 * must be a non-negative integer, `cacheScope` must be `'public'` or
 * `'private'`); invalid values are ignored rather than emitted.
 */
export function fillCacheFields(method: string, result: Result): Result {
    const fallback = cacheHintFallbackOf(result);
    const resultType = (result as Record<string, unknown>)['resultType'];

    if (resultType !== 'complete' || !isCacheableResultMethod(method)) {
        // Not a cache-fill target. Drop the configured-hint carrier if one was
        // attached so it never travels past the encode seam.
        return fallback === undefined ? result : stripCacheHintFallback(result);
    }

    const provided = result as Record<string, unknown>;
    const ttlMs = isValidCacheTtlMs(provided['ttlMs']) ? (provided['ttlMs'] as number) : resolveTtlMs(fallback);
    const cacheScope = isValidCacheScope(provided['cacheScope']) ? (provided['cacheScope'] as string) : resolveCacheScope(fallback);

    const filled = { ...provided, ttlMs, cacheScope } as Record<string | symbol, unknown>;
    delete filled[RESULT_CACHE_HINT_FALLBACK];
    return filled as Result;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/**
 * Step 3 of the encode contract: stamp the server's identity into the
 * result's `_meta` under `io.modelcontextprotocol/serverInfo` (spec PR #3002:
 * servers SHOULD include it on every response).
 *
 * - No `serverInfo` supplied (a client instance, or a hand-constructed
 *   protocol object) → identity function.
 * - The result's `_meta` already carries the key → kept as-is (the handler
 *   is the more specific author; mirrors the cache-fill resolution order).
 * - A present-but-non-object `_meta` (a dynamic-caller bug) → kept as-is:
 *   the stamp never rewrites handler material, and the malformed value fails
 *   loudly at the peer instead of being silently replaced here.
 * - Otherwise → the key is added, preserving any other `_meta` entries.
 *
 * Runs for every result regardless of `resultType`: the anchor types
 * `Result._meta` as `ResultMetaObject` on all results, `input_required`
 * included.
 */
export function stampServerInfoMeta(result: Result, serverInfo: Implementation | undefined): Result {
    if (serverInfo === undefined) return result;
    const meta = (result as Record<string, unknown>)['_meta'];
    if (meta === undefined) {
        return { ...result, _meta: { [SERVER_INFO_META_KEY]: serverInfo } } as Result;
    }
    if (!isPlainObject(meta)) return result;
    // Value check, not `in`: a present-but-undefined key (an unset optional in
    // handler code) must not suppress the stamp — JSON would drop the key and
    // the response would ship with no identity at all.
    if (meta[SERVER_INFO_META_KEY] !== undefined) return result;
    return { ...result, _meta: { ...meta, [SERVER_INFO_META_KEY]: serverInfo } } as Result;
}

function resolveTtlMs(fallback: CacheHint | undefined): number {
    return fallback !== undefined && isValidCacheTtlMs(fallback.ttlMs) ? fallback.ttlMs : DEFAULT_CACHE_TTL_MS;
}

function resolveCacheScope(fallback: CacheHint | undefined): string {
    return fallback !== undefined && isValidCacheScope(fallback.cacheScope) ? fallback.cacheScope : DEFAULT_CACHE_SCOPE;
}

function stripCacheHintFallback(result: Result): Result {
    const copy = { ...result } as Record<string | symbol, unknown>;
    delete copy[RESULT_CACHE_HINT_FALLBACK];
    return copy as Result;
}
/**
 * In-band input-request vocabulary of the 2026-07-28 revision (SEP-2322
 * multi round-trip requests), dispatch view.
 *
 * The three former server→client wire requests (`elicitation/create`,
 * `sampling/createMessage`, `roots/list`) are NOT wire request methods on
 * this revision — they are demoted to de-JSON-RPC'd payloads embedded in an
 * `input_required` result. The multi-round-trip driver dispatches those
 * embedded payloads to the client's registered handlers through the normal
 * handler machinery, and these are the schemas that dispatch parses them
 * with: lenient where the anchor's wire-true artifacts are strict (an
 * embedded request never carries the per-request `_meta` envelope), exact
 * where the vocabulary forks (the sampling shapes compose the forked
 * SamplingMessage/Tool payloads).
 *
 * Registry membership is intentionally NOT granted here — these methods stay
 * absent from the 2026-era request registry (a peer sending one as a wire
 * request still gets −32601 by absence). Only the codec's
 * `inputRequestSchema`/`inputResponseSchema` accessors expose them.
 */
import * as z from 'zod/v4';

import type { RequestMethod, RequestTypeMap, ResultTypeMap } from '../../types/types';
import { buildSchemas2026 } from './buildSchemas';

/** The embedded input-request methods of the 2026-07-28 revision. */
export const INPUT_REQUEST_METHODS_2026 = ['elicitation/create', 'sampling/createMessage', 'roots/list'] as const;

export type InputRequestMethod2026 = (typeof INPUT_REQUEST_METHODS_2026)[number];

/* The embedded-request maps are built lazily through the era's memoized
 * schema factory (`buildSchemas2026`) so importing this module constructs no
 * zod schemas; the maps themselves are memoized alongside. */
interface InputSchemaMaps {
    /** Dispatch-time (lenient) embedded request schemas, keyed by method. */
    readonly request: Record<InputRequestMethod2026, z.ZodType>;
    /** Embedded (bare) response schemas, keyed by the request method they answer. */
    readonly response: Record<InputRequestMethod2026, z.ZodType>;
}

let maps: InputSchemaMaps | undefined;

function inputSchemaMaps(): InputSchemaMaps {
    if (maps) return maps;
    const s = buildSchemas2026();
    maps = {
        request: {
            'elicitation/create': z.object({
                method: z.literal('elicitation/create'),
                params: s.ElicitRequestParamsSchema
            }),
            'sampling/createMessage': z.object({
                method: z.literal('sampling/createMessage'),
                params: s.CreateMessageRequestParamsSchema
            }),
            'roots/list': z.object({
                method: z.literal('roots/list'),
                params: z.looseObject({}).optional()
            })
        },
        response: {
            'elicitation/create': s.ElicitResultSchema,
            'sampling/createMessage': s.CreateMessageResultSchema,
            'roots/list': s.ListRootsResultSchema
        }
    };
    return maps;
}

/**
 * Forces the lazy embedded-request maps (and, through them, the era's schema
 * memo). Warm-up hook for `preloadSchemas()` — no-op once the maps exist.
 */
export function warmInputSchemaMaps2026(): void {
    inputSchemaMaps();
}

export function isInputRequestMethod2026(method: string): method is InputRequestMethod2026 {
    return (INPUT_REQUEST_METHODS_2026 as readonly string[]).includes(method);
}

/**
 * Gets the dispatch (lenient) schema for an embedded input request, or
 * `undefined` for methods that are not in-band vocabulary on this era.
 * The typed overload mirrors `WireCodec.inputRequestSchema`.
 */
export function getInputRequestSchema2026<M extends RequestMethod>(method: M): z.ZodType<RequestTypeMap[M]> | undefined;
export function getInputRequestSchema2026(method: string): z.ZodType | undefined;
export function getInputRequestSchema2026(method: string): z.ZodType | undefined {
    return isInputRequestMethod2026(method) ? inputSchemaMaps().request[method] : undefined;
}

/**
 * Gets the bare embedded-response schema answering an embedded input request,
 * or `undefined` for methods that are not in-band vocabulary on this era.
 */
export function getInputResponseSchema2026<M extends RequestMethod>(method: M): z.ZodType<ResultTypeMap[M]> | undefined;
export function getInputResponseSchema2026(method: string): z.ZodType | undefined;
export function getInputResponseSchema2026(method: string): z.ZodType | undefined {
    return isInputRequestMethod2026(method) ? inputSchemaMaps().response[method] : undefined;
}
/**
 * The 2026-era method registries (protocol revision 2026-07-28).
 *
 * Registry membership IS the deletion story: there are NO entries for
 * `initialize`, `notifications/initialized`, `ping`, `logging/setLevel`,
 * `resources/subscribe`, `resources/unsubscribe`,
 * `notifications/roots/list_changed`, `notifications/elicitation/complete`
 * (removed from the draft schema; 2025-11-25-only vocabulary), the task
 * family, or the server→client wire-request channel — so an era-mismatched
 * method falls to −32601 by absence inbound and a typed local error outbound,
 * with no table to forget.
 *
 * HAND-REGISTRY SEED DECISIONS (pinned by the CI registry-diff oracle, which
 * fails LOUD if this list and the anchor diff ever disagree):
 * - `sampling/createMessage`, `elicitation/create`, `roots/list`: the anchor
 *   still carries their method literals on bare interfaces, but 2026 DEMOTES
 *   them from wire requests to in-band `InputRequest` payloads — the entire
 *   server→client JSON-RPC request channel is deleted (`ServerRequest` has
 *   no 2026 export). A generator walking method literals would re-admit them
 *   (the ATK-D flavor-b trap); this hand registry excludes them by
 *   construction. Their in-band role lands with the MRTR driver (#13).
 * - `subscriptions/listen` + `notifications/subscriptions/acknowledged`
 *   (SEP-1865): 2026-only vocabulary, present here as registry shells.
 *   Dispatch never reaches a registered handler — the serving entries
 *   (`createMcpHandler`, `serveStdio`) recognize listen at the entry layer
 *   and own ack/filter/stamp/teardown themselves; on the client side
 *   `Client.listen()` sends directly on the transport (string-typed
 *   request id, transport-level demux) rather than via `request()`.
 *
 * LAZY SCHEMA CONSTRUCTION: method membership and the exported method lists
 * are static (null-valued key objects below, mapped over the hand-registry
 * unions so drift is a compile error in both directions), while the dispatch
 * schema maps are pulled through the era's memoized `buildSchemas2026()`
 * factory on first lookup — importing this module constructs no zod schemas.
 */
import type * as z from 'zod/v4';

import type { NotificationMethod, NotificationTypeMap, RequestMethod, RequestTypeMap, ResultTypeMap } from '../../types/types';
import type { Rev2026NotificationMethod, Rev2026RequestMethod } from './buildSchemas';
import { buildSchemas2026 } from './buildSchemas';

/* Static method membership — the schema-free half of the registry. Key order
 * matches the dispatch maps in `./buildSchemas.ts` so the exported method
 * lists are byte-identical to the pre-lazy `Object.keys(map)` derivation. */
const requestMethodKeys: { readonly [M in Rev2026RequestMethod]: null } = {
    'tools/call': null,
    'tools/list': null,
    'prompts/get': null,
    'prompts/list': null,
    'resources/list': null,
    'resources/templates/list': null,
    'resources/read': null,
    'completion/complete': null,
    'server/discover': null,
    'subscriptions/listen': null
};

const notificationMethodKeys: { readonly [M in Rev2026NotificationMethod]: null } = {
    'notifications/cancelled': null,
    'notifications/progress': null,
    'notifications/message': null,
    'notifications/resources/updated': null,
    'notifications/resources/list_changed': null,
    'notifications/tools/list_changed': null,
    'notifications/prompts/list_changed': null,
    'notifications/subscriptions/acknowledged': null
};

/** The 2026-era request-method set (registry membership = the deletion story). */
export function hasRequestMethod2026(method: string): method is Rev2026RequestMethod {
    return Object.prototype.hasOwnProperty.call(requestMethodKeys, method);
}

/** The 2026-era notification-method set. */
export function hasNotificationMethod2026(method: string): method is Rev2026NotificationMethod {
    return Object.prototype.hasOwnProperty.call(notificationMethodKeys, method);
}

/** Result-map membership (same key set as the request map on this era). */
function hasResultMethod2026(method: string): method is Rev2026RequestMethod {
    return Object.prototype.hasOwnProperty.call(requestMethodKeys, method);
}

/**
 * Gets the dispatch (post-lift) Zod schema for a given request method.
 * Returns `undefined` for methods this era's registry does not define.
 * The typed overload mirrors `WireCodec.requestSchema` so call sites with a
 * statically known method need no type assertion.
 */
export function getRequestSchema2026<M extends RequestMethod>(method: M): z.ZodType<RequestTypeMap[M]> | undefined;
export function getRequestSchema2026(method: string): z.ZodType | undefined;
export function getRequestSchema2026(method: string): z.ZodType | undefined {
    return hasRequestMethod2026(method) ? buildSchemas2026().dispatchRequestSchemas[method] : undefined;
}

/**
 * Gets the dispatch (post-lift) Zod schema for validating results of a given
 * request method. Returns `undefined` for methods this era's registry does
 * not define.
 * @see getRequestSchema2026 for the typed-overload contract.
 */
export function getResultSchema2026<M extends RequestMethod>(method: M): z.ZodType<ResultTypeMap[M]> | undefined;
export function getResultSchema2026(method: string): z.ZodType | undefined;
export function getResultSchema2026(method: string): z.ZodType | undefined {
    return hasResultMethod2026(method) ? buildSchemas2026().dispatchResultSchemas[method] : undefined;
}

/**
 * Gets the Zod schema for a given notification method.
 * Returns `undefined` for methods this era's registry does not define.
 * @see getRequestSchema2026 for the typed-overload contract.
 */
export function getNotificationSchema2026<M extends NotificationMethod>(method: M): z.ZodType<NotificationTypeMap[M]> | undefined;
export function getNotificationSchema2026(method: string): z.ZodType | undefined;
export function getNotificationSchema2026(method: string): z.ZodType | undefined {
    return hasNotificationMethod2026(method) ? buildSchemas2026().notificationSchemas2026[method] : undefined;
}

/** Registry method lists (for the spec-method universe and the CI registry-diff oracle). */
export const rev2026RequestMethods: readonly string[] = Object.keys(requestMethodKeys);
export const rev2026NotificationMethods: readonly string[] = Object.keys(notificationMethodKeys);
/**
 * The 2026-era wire codec (protocol revision 2026-07-28).
 *
 * Decode = raw-first `resultType` discrimination (the structural V-1 home:
 * the RAW value is inspected BEFORE any schema validation, so a non-complete
 * result can never be masked into a hollow success by a tolerant schema),
 * then wire-exact parse, then lift (drop the wire member). Encode = the
 * stamp seam: the known deleted-field set is strictly enforced (Q1-SD3 iii) —
 * the 2026 wire types have no slot for `execution.taskSupport` or
 * `capabilities.tasks`, so the encode mapping deletes them; era-blind
 * handlers stay era-invisible while deleted vocabulary cannot cross eras
 * through the parse-free outbound path — and then the encode contract steps
 * run (see `encodeContract.ts`): the `resultType` stamp (with handler
 * pass-through for the multi round-trip methods) followed by the required
 * `ttlMs`/`cacheScope` fill on cacheable results.
 *
 * Q1-SD3 postures implemented here:
 * (i)  absent `resultType` from a 2026-classified peer → typed error NAMING
 *      the violation. The spec's absent⇒complete bridge is scoped to
 *      EARLIER-revision servers (spec.types.2026-07-28.ts Result.resultType:
 *      "Servers implementing this protocol version MUST include this field")
 *      and is deliberately NOT extended to modern traffic.
 * (ii) `input_required` → the driver-seam payload (the multi-round-trip
 *      driver, M4.1/#13, consumes it; until then the protocol layer surfaces
 *      the discriminated kind as a typed local error, no retry).
 * (iii) unrecognized kinds → invalid, no retry (DQ5).
 */
import type * as z from 'zod/v4';

import { SdkError, SdkErrorCode } from '../../errors/sdkErrors';
import { CLIENT_CAPABILITIES_META_KEY, CLIENT_INFO_META_KEY, LOG_LEVEL_META_KEY, PROTOCOL_VERSION_META_KEY } from '../../types/constants';
import type { CallToolResult, Implementation, Result } from '../../types/types';
import type { DecodedResult, EnvelopeIssue, LiftedWireMaterial, OutboundEnvelopeMaterial, ValidateOutcome, WireCodec } from '../codec';
import { appendTextFallbackForNonObject } from '../textFallback';
import { buildSchemas2026 } from './buildSchemas';
import { fillCacheFields, stampResultType, stampServerInfoMeta } from './encodeContract';
import { getInputRequestSchema2026, getInputResponseSchema2026 } from './inputRequired';
import {
    getNotificationSchema2026,
    getRequestSchema2026,
    getResultSchema2026,
    hasNotificationMethod2026,
    hasRequestMethod2026
} from './registry';

function isPlainObject(value: unknown): value is Record<string, unknown> {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/** Tri-state wrap of an optional Zod schema lookup (the function-only contract). */
function triState<T>(schema: z.ZodType<T> | undefined, raw: unknown): ValidateOutcome<T> {
    if (schema === undefined) return { ok: false, reason: 'not-in-era' };
    const parsed = schema.safeParse(raw);
    return parsed.success ? { ok: true, value: parsed.data } : { ok: false, reason: 'invalid', message: String(parsed.error) };
}

const NOT_IN_ERA: ValidateOutcome<never> = { ok: false, reason: 'not-in-era' };

/**
 * The reserved `_meta` keys an envelope must carry on this era (in reporting
 * order). `clientInfo` is NOT here: spec PR #3002 demoted it to SHOULD, so a
 * request without it is accepted (a present-but-malformed value still fails
 * the envelope schema parse below).
 */
const REQUIRED_ENVELOPE_KEYS: readonly string[] = [PROTOCOL_VERSION_META_KEY, CLIENT_CAPABILITIES_META_KEY];

/** Strip the known deleted-field set from an outbound result (Q1-SD3 iii). */
function enforceDeletedFields(method: string, result: Result): Result {
    let next: Record<string, unknown> = result as Record<string, unknown>;
    let copied = false;
    const copy = () => {
        if (!copied) {
            next = { ...next };
            copied = true;
        }
        return next;
    };

    // tools arrays: execution (the taskSupport carrier) is deleted vocabulary.
    const tools = (result as { tools?: unknown }).tools;
    if (method === 'tools/list' && Array.isArray(tools) && tools.some(tool => isPlainObject(tool) && 'execution' in tool)) {
        copy().tools = tools.map(tool => {
            if (!isPlainObject(tool) || !('execution' in tool)) return tool;
            const rest = { ...tool };
            delete rest['execution'];
            return rest;
        });
    }

    // capability objects: the `tasks` capability is deleted vocabulary.
    const capabilities = (result as { capabilities?: unknown }).capabilities;
    if (isPlainObject(capabilities) && 'tasks' in capabilities) {
        const rest = { ...capabilities };
        delete rest['tasks'];
        copy().capabilities = rest;
    }

    return next as Result;
}

export const rev2026Codec: WireCodec & {
    /**
     * @deprecated Off-interface in-band registry probe retained for the
     * existing inputRequiredFunnel pin. Use {@link WireCodec.validateInputRequest}
     * — its `not-in-era` outcome is the membership signal.
     */
    inputRequestSchema(method: string): unknown;
} = {
    era: '2026-07-28',

    hasRequestMethod: hasRequestMethod2026,
    hasNotificationMethod: hasNotificationMethod2026,
    hasInputRequestMethod: (method: string): boolean => getInputRequestSchema2026(method) !== undefined,

    // ── Function-only validation surface ──
    validateRequest: (method: string, raw: unknown) => triState(getRequestSchema2026(method), raw),
    validateResult: (method: string, raw: unknown) => triState(getResultSchema2026(method), raw),
    validateNotification: (method: string, raw: unknown) => triState(getNotificationSchema2026(method), raw),
    // In-band multi-round-trip vocabulary: the demoted elicitation/sampling/
    // roots shapes carried inside `input_required` results (NOT wire request
    // methods on this era — registry membership is deliberately not granted).
    validateInputRequest: (method: string, raw: unknown) => triState(getInputRequestSchema2026(method), raw),
    validateInputResponse: (method: string, raw: unknown) => triState(getInputResponseSchema2026(method), raw),

    // Sampling is in-band on this era — callers fall through to
    // `validateInputResponse('sampling/createMessage', …)`.
    samplingResultVariant: (): ValidateOutcome<never> => NOT_IN_ERA,

    outboundEnvelope(material: OutboundEnvelopeMaterial): Readonly<Record<string, unknown>> {
        return {
            [PROTOCOL_VERSION_META_KEY]: material.protocolVersion,
            [CLIENT_INFO_META_KEY]: material.clientInfo,
            [CLIENT_CAPABILITIES_META_KEY]: material.clientCapabilities,
            ...(material.logLevel !== undefined && { [LOG_LEVEL_META_KEY]: material.logLevel })
        };
    },

    validateEnvelopeMeta(meta: Readonly<Record<string, unknown>>): EnvelopeIssue[] {
        const issues: EnvelopeIssue[] = [];
        for (const key of REQUIRED_ENVELOPE_KEYS) {
            if (!(key in meta)) issues.push({ key, problem: 'missing' });
        }
        const parsed = buildSchemas2026().RequestMetaEnvelopeSchema.safeParse(meta);
        if (!parsed.success) {
            for (const issue of parsed.error.issues) {
                const path = issue.path.map(String);
                const key = path.length > 0 ? path.join('.') : '_meta';
                // Missing required keys were already reported above in canonical order.
                if (path.length === 1 && issues.some(existing => existing.key === key && existing.problem === 'missing')) {
                    continue;
                }
                issues.push({ key, problem: issue.message });
            }
        }
        return issues;
    },

    // SEP-2106 result-side projection: no `{result:…}` wrap on the modern era
    // (the wire shape carries the natural `structuredContent` directly), but
    // the era-agnostic §4.3 TextContent auto-append still applies.
    projectCallToolResult: (result: CallToolResult): CallToolResult => appendTextFallbackForNonObject(result),

    // Retained off-interface for the inputRequiredFunnel registry-membership
    // pin (asserts the in-band schema set without exercising parse): the
    // function-only WireCodec contract carries no schema-returning members,
    // so this lives only on the concrete object's widened type.
    inputRequestSchema: getInputRequestSchema2026,

    decodeResult(method: string, raw: unknown): DecodedResult {
        if (!isPlainObject(raw)) {
            return {
                kind: 'invalid',
                error: new SdkError(SdkErrorCode.InvalidResult, `Invalid result for ${method}: not an object`, { method })
            };
        }

        // Step 1 — RAW discrimination, before any schema (V-1).
        const rawResultType = raw['resultType'];
        if (rawResultType === undefined) {
            // Q1-SD3 (i): hard error naming the violation.
            return {
                kind: 'invalid',
                error: new SdkError(
                    SdkErrorCode.InvalidResult,
                    `Invalid result for ${method}: missing required resultType — servers implementing protocol revision 2026-07-28 ` +
                        `MUST include it (the absent-means-complete bridge applies only to earlier-revision servers)`,
                    { method, violation: 'missing-resultType' }
                )
            };
        }
        if (typeof rawResultType !== 'string') {
            return {
                kind: 'invalid',
                error: new SdkError(SdkErrorCode.InvalidResult, `Invalid result for ${method}: non-string resultType`, {
                    method,
                    resultType: rawResultType
                })
            };
        }
        if (rawResultType === 'input_required') {
            // The driver seam (#13 consumes this payload).
            const rawInputRequests = raw['inputRequests'];
            const inputRequests = isPlainObject(rawInputRequests) ? rawInputRequests : {};
            const requestState = raw['requestState'];
            if (Object.keys(inputRequests).length === 0 && typeof requestState !== 'string') {
                // At-least-one rule, client side: with neither inputRequests
                // nor requestState there is nothing to fulfil and nothing to
                // echo — retrying would only resend the original params until
                // the round cap is exhausted, so fail fast instead.
                return {
                    kind: 'invalid',
                    error: new SdkError(
                        SdkErrorCode.InvalidResult,
                        `Invalid result for ${method}: input_required carries neither inputRequests nor requestState ` +
                            `(every input_required result must include at least one of the two)`,
                        { method, violation: 'input-required-missing-both' }
                    )
                };
            }
            return {
                kind: 'input_required',
                inputRequests,
                ...(typeof requestState === 'string' && { requestState })
            };
        }
        if (rawResultType !== 'complete') {
            // Unrecognized kind ⇒ invalid, no retry (DQ5).
            return {
                kind: 'invalid',
                error: new SdkError(SdkErrorCode.UnsupportedResultType, `Unsupported result type '${rawResultType}' for ${method}`, {
                    resultType: rawResultType,
                    method
                })
            };
        }

        // Step 2 — wire-exact parse (registry methods), with resultType present.
        // Own-key lookup: `method` is peer-influenced on related-request
        // paths, and a prototype-chain hit (e.g. 'constructor') must not
        // masquerade as a schema and throw out of the decode hop.
        const wireResultSchemas = getWireResultSchemas();
        const wireSchema = Object.hasOwn(wireResultSchemas, method) ? wireResultSchemas[method] : undefined;
        if (wireSchema !== undefined) {
            const parsed = wireSchema.safeParse(raw);
            if (!parsed.success) {
                return {
                    kind: 'invalid',
                    error: new SdkError(SdkErrorCode.InvalidResult, `Invalid result for ${method}: ${parsed.error}`, { method })
                };
            }
        }

        // Step 3 — lift: the wire discriminator is consumed.
        const lifted = { ...raw };
        delete lifted['resultType'];
        return { kind: 'complete', result: lifted as Result };
    },

    encodeResult(method: string, result: Result, serverInfo?: Implementation): Result {
        // The stamp seam, in pinned order: deleted-field strictness, then the
        // resultType stamp (handler pass-through only for methods whose
        // vocabulary goes beyond 'complete'), then the cache fill for the
        // cacheable operations (only on post-stamp 'complete' results), then
        // the `_meta` serverInfo identity stamp (#3002 — every result,
        // handler-authored value wins).
        return stampServerInfoMeta(fillCacheFields(method, stampResultType(method, enforceDeletedFields(method, result))), serverInfo);
    },

    // The −32002 resource-not-found domain code maps to −32602 Invalid Params
    // on the wire (the 2026-07-28 spec MUST for resources/read misses).
    encodeErrorCode: (code: number): number => (code === -32_002 ? -32_602 : code),

    checkInboundEnvelope(material: LiftedWireMaterial): string | undefined {
        if (material.envelope === undefined) {
            return (
                'Request is missing the required _meta envelope for protocol revision 2026-07-28 ' +
                '(io.modelcontextprotocol/protocolVersion, io.modelcontextprotocol/clientCapabilities)'
            );
        }
        const parsed = buildSchemas2026().RequestMetaEnvelopeSchema.safeParse(material.envelope);
        if (!parsed.success) {
            return `Invalid _meta envelope for protocol revision 2026-07-28: ${parsed.error.issues.map(issue => issue.message).join('; ')}`;
        }
        return undefined;
    }
};

/** Wire-true result wrappers consulted by decode step 2, keyed by method —
 * built once through the era's schema memo on the first decode. */
let wireResultSchemasMemo: Record<string, z.ZodType> | undefined;

function getWireResultSchemas(): Record<string, z.ZodType> {
    if (wireResultSchemasMemo) return wireResultSchemasMemo;
    const s = buildSchemas2026();
    wireResultSchemasMemo = {
        'tools/call': s.CallToolResultSchema,
        'tools/list': s.ListToolsResultSchema,
        'prompts/get': s.GetPromptResultSchema,
        'prompts/list': s.ListPromptsResultSchema,
        'resources/list': s.ListResourcesResultSchema,
        'resources/templates/list': s.ListResourceTemplatesResultSchema,
        'resources/read': s.ReadResourceResultSchema,
        'completion/complete': s.CompleteResultSchema,
        'server/discover': s.DiscoverResultSchema
    };
    return wireResultSchemasMemo;
}

/**
 * Forces the lazy wire-result wrapper map (and, through it, the era's schema
 * memo). Warm-up hook for `preloadSchemas()` — no-op once the map exists.
 */
export function warmWireResultSchemas2026(): void {
    getWireResultSchemas();
}
/**
 * The era-granular wire-codec layer (Q1 increment 2).
 *
 * The SDK separates a revision-neutral model layer (the public types — no
 * `resultType`, no `_meta` envelope keys, no retry fields) from per-revision
 * WIRE CODECS that own revision-exact schemas, method registries, and the
 * decode (wire → neutral lift) / encode (neutral → wire stamp) transforms.
 * The codec is a pure function of the negotiated protocol version, which is
 * ordinary connection state on the `Protocol` instance: the client stores it
 * when its handshake completes, the server stores it at `_oninitialize` (and
 * modern-era server instances get it set at instance binding by the entry).
 * There is no side table — era resolution is `codecForVersion(<instance
 * state>)`, with the pre-negotiation window covered by the outbound method
 * pins in `bootstrap.ts`.
 *
 * REQUIRED DISCLOSURE (Q1-SD1, era granularity): "the negotiated version
 * determines which types are serialized/deserialized over the wire" cashes
 * out as "the negotiated wire ERA determines them". All five legacy protocol
 * versions (2024-10-07 … 2025-11-25) share one wire vocabulary and map to the
 * single 2025-era codec — exactly how the single schema set already served
 * all five — and '2026-07-28' maps to the 2026-era codec. A new codec exists
 * only when wire vocabulary actually diverges; intra-era vocabulary is NOT
 * keyed by exact version.
 *
 * Deletions are physical: registry membership is the deletion story. The
 * 2026-era registry has no `tasks/*`, `initialize`, `ping`, `logging/setLevel`,
 * `resources/(un)subscribe` or server→client wire-request entries, so an
 * inbound era-mismatched method falls to −32601 by absence — even when a
 * handler is registered — and an outbound one dies locally with a typed
 * `SdkError` before anything reaches the transport. The 2025-era registry has
 * no `server/discover`/`subscriptions/listen`/MRTR entries, symmetrically.
 *
 * Custom-handler shadowing policy (both directions): a method that belongs to
 * the SPEC-METHOD UNIVERSE — the union of every codec's registry, derived,
 * not hand-curated — is ALWAYS era-gated, so a custom handler registered for
 * a deleted spec method (e.g. `tasks/get`) serves it only on the era that
 * defines it. Methods outside the universe are consumer-owned extension
 * methods: they are era-blind and require explicit schemas, exactly as today.
 *
 * Everything in `wire/` is internal to the bundled, `private: true` core —
 * nothing per-revision is public surface, and nothing here may ever be
 * exported from `core/public`.
 */
import type { SdkError } from '../errors/sdkErrors';
import { isModernProtocolVersion } from '../shared/protocolEras';
import type {
    CallToolResult,
    ClientCapabilities,
    CreateMessageResult,
    CreateMessageResultWithTools,
    Implementation,
    LoggingLevel,
    MessageClassification,
    NotificationMethod,
    NotificationTypeMap,
    RequestMetaEnvelope,
    RequestMethod,
    RequestTypeMap,
    Result,
    ResultTypeMap
} from '../types/types';
import { rev2025Codec } from './rev2025-11-25/codec';
import { rev2026Codec } from './rev2026-07-28/codec';

/** Wire eras with distinct vocabulary. */
export type WireEra = '2025-11-25' | '2026-07-28';

/**
 * The modern wire revision literal. Internal only — deliberately NOT a public
 * constant (G-D2-4: no public modern-version constant ships before era-aware
 * list semantics exist).
 */
export const MODERN_WIRE_REVISION = '2026-07-28';

/**
 * Wire-only material lifted off an inbound message by the protocol layer
 * before dispatch (the V-3 seam): the reserved `_meta` envelope keys and the
 * multi-round-trip driver fields. This is the typed driver-material channel
 * of the codec contract — handlers never see it; the protocol layer surfaces
 * it via `ctx.mcpReq.envelope` / `.inputResponses` / `.requestState`, and the
 * MRTR driver (M4.1) consumes the retry fields from here.
 */
export interface LiftedWireMaterial {
    // Partial: the lift surfaces whichever reserved keys the message actually
    // carried — a peer on an adjacent revision may legally send a subset, and
    // envelope requiredness is enforced per request at dispatch time
    // (`checkInboundEnvelope`), not by the lift.
    envelope?: Partial<RequestMetaEnvelope>;
    inputResponses?: Record<string, unknown>;
    requestState?: string;
}

/**
 * Tri-state validation outcome — the function-only contract for what the
 * schema-getter pair (`hasRequestMethod` ⇒ −32601-by-absence; `…Schema(m)
 * .parse` throw ⇒ −32602) used to encode in two pieces. Preserving the split
 * is the point: collapsing 'absent from this era's registry' into 'invalid'
 * would make the in-band fallback chain (validate → on `not-in-era` fall to
 * validateInputRequest) treat absence as failure and never fall through.
 */
export type ValidateOutcome<T> =
    | { readonly ok: true; readonly value: T }
    /**
     * Method is spec vocabulary but absent from THIS era's registry. Callers
     * map to −32601 (inbound) or a typed local SdkError (outbound), or fall
     * through to the in-band validator.
     */
    | { readonly ok: false; readonly reason: 'not-in-era' }
    /**
     * Method is in this era's registry; payload failed the era-exact schema.
     * Callers map to −32602.
     */
    | { readonly ok: false; readonly reason: 'invalid'; readonly message: string };

/** A single self-identifying problem found while validating a per-request `_meta` envelope. */
export interface EnvelopeIssue {
    /**
     * The envelope key the problem is about: one of the reserved `_meta`
     * keys, or a dotted path inside one.
     */
    readonly key: string;
    /** A short description of what is wrong with that key (`missing`, or a validation message). */
    readonly problem: string;
}

/** Material a Client supplies for an era to build its per-request `_meta` envelope from. */
export interface OutboundEnvelopeMaterial {
    readonly protocolVersion: string;
    readonly clientInfo: Implementation;
    readonly clientCapabilities: ClientCapabilities;
    readonly logLevel?: LoggingLevel;
}

/** Result decode outcomes — the raw-first discrimination (V-1) lives in `decodeResult`. */
export type DecodedResult =
    | {
          kind: 'complete';
          /** The neutral result value: wire-only material consumed/stripped. */
          result: Result;
      }
    | {
          kind: 'input_required';
          /**
           * Driver-only material (never consumer-visible). The full
           * multi-round-trip driver is M4.1 scope; this seam carries the
           * discriminated payload to it.
           */
          inputRequests: Record<string, unknown>;
          requestState?: string;
      }
    | { kind: 'invalid'; error: SdkError };

/**
 * The per-era wire codec contract (design C §3, adapted to the live funnel
 * layout: the universal wire-only LIFT runs once in the protocol layer for
 * every message — spec, custom, and fallback paths alike — and codecs consume
 * the lifted material rather than re-implementing the strip per era).
 */
export interface WireCodec {
    readonly era: WireEra;

    /** Registry membership — the deletion story (inbound −32601 by absence; outbound typed local error). */
    hasRequestMethod(method: string): boolean;
    hasNotificationMethod(method: string): boolean;
    hasInputRequestMethod(method: string): boolean;

    // ── Function-only validation surface ──────────────────────────────────
    // The validator-agnostic contract: callers never see a Zod schema, only a
    // tri-state outcome. The method-literal overloads carry the typed parse
    // result exactly as the (now-deprecated) *Schema getters did.

    /** Era-exact request validation. `not-in-era` ≡ −32601-by-absence; `invalid` ≡ −32602. */
    validateRequest<M extends RequestMethod>(method: M, raw: unknown): ValidateOutcome<RequestTypeMap[M]>;
    validateRequest(method: string, raw: unknown): ValidateOutcome<unknown>;

    /** Era-exact result validation (same registry as `validateRequest`). */
    validateResult<M extends RequestMethod>(method: M, raw: unknown): ValidateOutcome<ResultTypeMap[M]>;
    validateResult(method: string, raw: unknown): ValidateOutcome<unknown>;

    /** Era-exact notification validation. */
    validateNotification<M extends NotificationMethod>(method: M, raw: unknown): ValidateOutcome<NotificationTypeMap[M]>;
    validateNotification(method: string, raw: unknown): ValidateOutcome<unknown>;

    /**
     * In-band (de-JSON-RPC'd) input-request validation — the embedded
     * requests a multi-round-trip `input_required` result may carry. Always
     * `not-in-era` on the 2025 era (elicitation/sampling/roots are wire
     * request methods there). Does NOT grant registry membership.
     */
    validateInputRequest<M extends RequestMethod>(method: M, raw: unknown): ValidateOutcome<RequestTypeMap[M]>;
    validateInputRequest(method: string, raw: unknown): ValidateOutcome<unknown>;

    /** In-band bare-response validation answering an embedded input request. */
    validateInputResponse<M extends RequestMethod>(method: M, raw: unknown): ValidateOutcome<ResultTypeMap[M]>;
    validateInputResponse(method: string, raw: unknown): ValidateOutcome<unknown>;

    /**
     * Param-conditional `sampling/createMessage` result validation — the one
     * spec result whose schema depends on REQUEST params (tools vs no tools).
     * The 2025 era owns the with-tools/plain frozen schemas; the 2026 era
     * returns `not-in-era` (sampling is in-band there — callers fall through
     * to `validateInputResponse`).
     */
    samplingResultVariant(hasTools: true, raw: unknown): ValidateOutcome<CreateMessageResultWithTools>;
    samplingResultVariant(hasTools: false, raw: unknown): ValidateOutcome<CreateMessageResult>;
    samplingResultVariant(hasTools: boolean, raw: unknown): ValidateOutcome<CreateMessageResult | CreateMessageResultWithTools>;

    /**
     * Outbound per-request `_meta` envelope encode. Returns the keyed object
     * to merge into `params._meta` on this era, or `undefined` when this era
     * carries no per-request envelope (the 2025 era — legacy wire stays
     * byte-identical).
     */
    outboundEnvelope(material: OutboundEnvelopeMaterial): Readonly<Record<string, unknown>> | undefined;

    /**
     * Structured envelope validation: maps a `_meta` object to
     * self-identifying issues. The 2025 era never requires an envelope and
     * always returns `[]`; the 2026 era owns the required-key pre-pass plus
     * the wire-exact `RequestMetaEnvelopeSchema` parse.
     */
    validateEnvelopeMeta(meta: Readonly<Record<string, unknown>>): EnvelopeIssue[];

    /**
     * Per-registration `tools/call` result projection. Two independent
     * decisions, both owned here so server-side code never re-derives them:
     *
     * - SEP-2106 §4.3 TextContent auto-append (EVERY era, value-shape-based):
     *   when `structuredContent` is a non-object value (array/primitive/
     *   `null`) and the handler authored no `type:'text'` block, append
     *   `{type:'text', text: JSON.stringify(value)}` so consumers that read
     *   only `content` still receive a rendering. The author opts out by
     *   returning any `text` block themselves.
     *
     * - `{result:…}` wrap (2025 era only): wrap as `{result:<value>}` when the
     *   value is non-object (the 2025 wire shape requires `structuredContent`
     *   to be an object — a schema-less tool returning `[1,2,3]` would
     *   otherwise ship wire-illegal bytes) OR when the tool's ADVERTISED
     *   `outputSchema` has a non-object root (so the result matches the
     *   `encodeResult('tools/list')` projection of the same tool). Identity on
     *   the 2026 era — the wire shape carries the natural value directly.
     */
    projectCallToolResult(result: CallToolResult, advertisedOutputSchema: Readonly<Record<string, unknown>> | undefined): CallToolResult;

    /**
     * Step 1 of result decoding: RAW `resultType` handling BEFORE any schema
     * validation (V-1's structural home). Era postures (Q1-SD3):
     * - 2026 era: required discriminator — absent ⇒ typed error naming the
     *   spec violation; `input_required` ⇒ driver payload; unknown ⇒ invalid,
     *   no retry; `complete` ⇒ consume + lift.
     * - 2025 era: `resultType` is foreign vocabulary ⇒ strip-on-lift.
     */
    decodeResult(method: string, raw: unknown): DecodedResult;

    /**
     * Outbound result mapping (the stamp seam). The 2025-era codec is the
     * identity — it has NO stamp code path (the never-stamp guarantee; it
     * never reads `serverInfo`). The 2026-era codec strictly enforces the
     * 2026 wire shape for the known deleted-field set
     * (`execution.taskSupport`, `capabilities.tasks` — Q1-SD3 iii), stamps
     * `resultType`, fills the required `ttlMs`/`cacheScope` fields on
     * cacheable results, and — when the caller supplies its identity —
     * stamps `_meta['io.modelcontextprotocol/serverInfo']` on every result
     * (spec PR #3002 SHOULD; a handler-authored value wins). `Server`
     * instances pass their identity; clients and hand-constructed protocol
     * objects pass nothing and no identity is ever invented.
     */
    encodeResult(method: string, result: Result, serverInfo?: Implementation): Result;

    /**
     * Outbound error-code mapping (the error half of the stamp seam). A
     * handler-thrown `ProtocolError`'s numeric code passes through here on
     * its way to the JSON-RPC error response, so per-era wire-code selection
     * lives in the codec rather than in handler/funnel code. The current
     * mapping is identical on both eras (the `-32002` resource-not-found
     * domain code maps to `-32602` Invalid Params on the wire — the
     * 2026-07-28 spec MUST, and what the deployed v1.x SDK already emits on
     * earlier revisions); the seam is the structural home for any future
     * per-era divergence. Unknown codes pass through unchanged.
     */
    encodeErrorCode(code: number): number;

    /**
     * @deprecated Use {@link validateEnvelopeMeta}. Inbound envelope
     * enforcement for era-classified traffic: validates the lifted envelope
     * material of a request. Returns an error message when the era requires
     * an envelope and it is missing/invalid (→ −32602 at the dispatch
     * layer); `undefined` when acceptable. The 2025 era never requires an
     * envelope.
     */
    checkInboundEnvelope(material: LiftedWireMaterial): string | undefined;
}

/**
 * Era resolution, many-to-one (Q1-SD1): every modern-era revision
 * (`>= 2026-07-28`) → the 2026-era codec; every legacy revision (the five
 * `SUPPORTED_PROTOCOL_VERSIONS`) and `undefined`/unknown → the 2025-era
 * codec (the DV-13 default posture — hand-constructed instances and
 * unclassified traffic are legacy-era). This is the same era predicate the
 * rest of the SDK uses ({@link isModernProtocolVersion}); a pinned modern
 * revision other than the literal '2026-07-28' must still resolve modern.
 */
export function codecForVersion(version: string | undefined): WireCodec {
    return version !== undefined && isModernProtocolVersion(version) ? rev2026Codec : rev2025Codec;
}

/**
 * The wire era an edge classification names (Q2 — produced at the
 * transport/entry edge; this layer only CONSUMES it). The dispatch funnel no
 * longer resolves a codec FROM the classification: era is instance state, and
 * a classified inbound message is VALIDATED against the instance era — a
 * mismatch is an entry/routing error, never a per-message era switch. The
 * exact `revision` wins over the coarse era flag when both are present.
 */
export function classifiedWireEra(classification: MessageClassification): WireEra {
    if (classification.revision !== undefined) return codecForVersion(classification.revision).era;
    return classification.era === 'modern' ? rev2026Codec.era : rev2025Codec.era;
}

/**
 * The derived spec-method universe: the union of every codec registry. A
 * method in this set is era-gated at dispatch and send time; a method outside
 * it is a consumer-owned extension method (era-blind, schema-explicit).
 * Derived from the registries — never hand-curated (the LEGACY_ONLY_METHODS
 * table class is exactly what registry membership replaces).
 */
export function isSpecRequestMethod(method: string): boolean {
    return ALL_CODECS.some(codec => codec.hasRequestMethod(method));
}

export function isSpecNotificationMethod(method: string): boolean {
    return ALL_CODECS.some(codec => codec.hasNotificationMethod(method));
}

