/* ------------------------------------------------------------------------ *
 * HTTP status mapping for ladder-originated errors
 * ------------------------------------------------------------------------ */

/**
 * HTTP status for ladder-originated JSON-RPC error codes.
 *
 * Keyed on origin, not on the bare code: this table only applies to errors
 * the ladder (or a pre-handler protocol gate) produced. Errors produced by
 * request handlers — whatever their code — stay in-band on HTTP 200, and are
 * never mapped to an HTTP status by this table; in particular `-32603` and
 * domain-specific codes never become a blanket 500. The single exception is
 * `MissingRequiredClientCapability` (-32021) — see
 * {@linkcode httpStatusForErrorCode}.
 *
 * `-32602` (invalid params) deliberately has NO entry: the only invalid-params
 * rejection that maps to HTTP 400 is the classifier's own envelope rung
 * short-circuit, which carries its HTTP status directly. A dispatch- or
 * handler-produced invalid-params error is always in-band.
 */
export const LADDER_ERROR_HTTP_STATUS: Readonly<Record<number, number>> = {
    [ProtocolErrorCode.ParseError]: 400,
    [ProtocolErrorCode.InvalidRequest]: 400,
    [ProtocolErrorCode.MethodNotFound]: 404,
    [ProtocolErrorCode.UnsupportedProtocolVersion]: 400,
    [ProtocolErrorCode.MissingRequiredClientCapability]: 400,
    [HEADER_MISMATCH_ERROR_CODE]: 400
};

/**
 * The HTTP status to answer a JSON-RPC error with, keyed on the error's
 * origin. `in-band` errors (anything produced by a request handler) are
 * HTTP 200 — the JSON-RPC error response is the payload, not an HTTP
 * failure — with ONE exception: `MissingRequiredClientCapability` (-32021),
 * whose 400 the spec mandates on the error itself with no origin condition,
 * and which the SDK genuinely produces after dispatch (the `input_required`
 * capability gate). A handler relaying some downstream peer's `-32020`/`-32022`
 * is NOT that peer's spec error and stays in-band like every other handler
 * code. `ladder` errors map through {@linkcode LADDER_ERROR_HTTP_STATUS}.
 *
 * The per-request transport intentionally does NOT delegate to this function:
 * its `?? 400` ladder fallback is only correct for entry-gate codes known to
 * the table, and would wrongly map dispatch-window errors outside it (a
 * window `-32602` must stay in-band on 200). The transport indexes the table
 * directly; keep the two in agreement when editing either.
 */
export function httpStatusForErrorCode(code: number, origin: 'ladder' | 'in-band'): number {
    if (origin === 'in-band') {
        return code === ProtocolErrorCode.MissingRequiredClientCapability ? 400 : 200;
    }
    return LADDER_ERROR_HTTP_STATUS[code] ?? 400;
}

/* ------------------------------------------------------------------------ *
 * The classifier
 * ------------------------------------------------------------------------ */

function rejection(
    rung: InboundValidationRung,
    cell: string,
    httpStatus: number,
    error: ProtocolError,
    settled: boolean
): InboundLadderRejection {
    return {
        kind: 'reject',
        rung,
        cell,
        httpStatus,
        code: error.code,
        message: error.message,
        ...(error.data !== undefined && { data: error.data }),
        settled
    };
}

function crossCheckMismatch(
    cell: string,
    header: string,
    body: string,
    rung: InboundValidationRung = 'era-classification'
): InboundLadderRejection {
    return rejection(
        rung,
        cell,
        400,
        new ProtocolError(HEADER_MISMATCH_ERROR_CODE, `Bad Request: the request headers and body disagree: ${body}`, {
            mismatch: { header, body }
        }),
        true
    );
}

/**
 * The methods whose body carries a `params.name` / `params.uri` value the
 * `Mcp-Name` header must mirror, and which body field supplies it (SEP-2243
 * § Standard Request Headers, `Required For` column).
 */
export const MCP_NAME_HEADER_SOURCE: Readonly<Record<string, 'name' | 'uri'>> = {
    'tools/call': 'name',
    'prompts/get': 'name',
    'resources/read': 'uri'
};

/** Strip RFC 9110 optional whitespace (SP / HTAB) around a field value in linear time. */
function stripHttpOws(value: string): string {
    let start = 0;
    while (start < value.length) {
        const code = value.codePointAt(start);
        if (code !== 0x09 && code !== 0x20) break;
        start += 1;
    }

    let end = value.length;
    while (end > start) {
        const code = value.codePointAt(end - 1);
        if (code !== 0x09 && code !== 0x20) break;
        end -= 1;
    }

    return start === 0 && end === value.length ? value : value.slice(start, end);
}

/**
 * SEP-2243 standard-header server-side validation, evaluated by the HTTP
 * entry on a modern-classified request immediately after
 * {@linkcode classifyInboundRequest} returns a modern route.
 *
 * Returns the `-32020` (`HeaderMismatch`) ladder rejection (HTTP `400`,
 * `standard-header-validation` rung — the same shape
 * {@linkcode classifyInboundRequest} already emits on the edge
 * `era-classification` rung for the `MCP-Protocol-Version` and
 * `Mcp-Method` *mismatch* cells) when:
 *
 * - the required `Mcp-Method` header is absent;
 * - the required `Mcp-Name` header is absent on a `tools/call`,
 *   `prompts/get`, or `resources/read` request whose body carries the
 *   `params.name` / `params.uri` value the header mirrors;
 * - the `Mcp-Name` header carries an invalid `=?base64?…?=` sentinel; or
 * - the (decoded) `Mcp-Name` value disagrees with the body's
 *   `params.name` / `params.uri`.
 *
 * Returns `undefined` (pass) for notifications (the spec table reads
 * "All requests"), for methods that have no `Mcp-Name` source, and when the
 * headers agree with the body. Never enforced on legacy traffic — the entry
 * only calls this on a modern route.
 *
 * Kept separate from {@linkcode classifyInboundRequest} so that a body-only
 * call to the classifier (no headers passed) keeps routing a modern request
 * unchanged: the classifier remains a pure body-primary router, and this
 * function is the presence/`Mcp-Name` half of the standard-header rung the
 * entry layers on top.
 */
export function validateStandardRequestHeaders(request: InboundHttpRequest, route: InboundModernRoute): InboundLadderRejection | undefined {
    if (route.messageKind !== 'request') {
        return undefined;
    }
    const method = route.message.method;

    if (request.mcpMethodHeader === undefined) {
        return crossCheckMismatch(
            'method-header-missing',
            '(missing)',
            `the body names method ${method} but the required Mcp-Method header is absent`,
            'standard-header-validation'
        );
    }

    // `method` is the JSON-RPC method string from the body — peer-controlled,
    // so guard the plain-object lookup against `Object.prototype` collisions
    // (`constructor`, `toString`, …) the same way the client-capability table
    // lookup does.
    const sourceField = Object.hasOwn(MCP_NAME_HEADER_SOURCE, method) ? MCP_NAME_HEADER_SOURCE[method] : undefined;
    if (sourceField === undefined) {
        return undefined;
    }
    const params = route.message.params as Record<string, unknown> | undefined;
    const sourceValue = params?.[sourceField];
    const bodyValue = typeof sourceValue === 'string' ? sourceValue : undefined;

    if (request.mcpNameHeader === undefined) {
        // The header is required for these methods whenever the body carries
        // the source value. A body without `params.name`/`params.uri` is a
        // params-validation failure further down the ladder; this rung only
        // answers the missing-header case it can observe.
        if (bodyValue === undefined) {
            return undefined;
        }
        return crossCheckMismatch(
            'name-header-missing',
            '(missing)',
            `the body carries params.${sourceField}="${bodyValue}" but the required Mcp-Name header is absent`,
            'standard-header-validation'
        );
    }

    const normalizedNameHeader = stripHttpOws(request.mcpNameHeader);
    const decoded = decodeMcpParamValue(normalizedNameHeader);
    if (decoded === undefined) {
        return crossCheckMismatch(
            'name-header-invalid-encoding',
            normalizedNameHeader,
            'the Mcp-Name header carries an invalid Base64 sentinel value',
            'standard-header-validation'
        );
    }
    if (bodyValue !== undefined && decoded !== bodyValue) {
        return crossCheckMismatch(
            'name-header-mismatch',
            normalizedNameHeader,
            `the body carries params.${sourceField}="${bodyValue}" but the Mcp-Name header names "${decoded}"`,
            'standard-header-validation'
        );
    }
    return undefined;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function classificationForClaim(claimedVersion: string | undefined): MessageClassification {
    if (claimedVersion === undefined) {
        return { era: 'modern' };
    }
    return { era: isModernProtocolVersion(claimedVersion) ? 'modern' : 'legacy', revision: claimedVersion };
}

/**
 * Whether a request's params carry a per-request envelope claim that is both
 * well-formed and names a modern protocol revision.
 *
 * Used by the `initialize` precedence rule: only such a claim overrides the
 * `initialize` ⇒ legacy-handshake classification — a request carrying a valid
 * modern envelope is a modern request regardless of its method name, and the
 * modern era then answers `initialize` exactly like any other method it does
 * not define (method-not-found). A malformed claim, or one naming a pre-2026
 * revision, keeps the legacy-handshake routing unchanged.
 *
 * Exported on the core internal barrel for the stdio serving entry, which
 * applies the same precedence rule to a connection's opening message; not
 * public API.
 */
export function carriesValidModernEnvelopeClaim(params: unknown): boolean {
    if (!hasEnvelopeClaim(params)) {
        return false;
    }
    const claimedVersion = envelopeClaimVersion(params);
    if (claimedVersion === undefined || !isModernProtocolVersion(claimedVersion)) {
        return false;
    }
    const meta = requestMetaOf(params);
    return meta !== undefined && validateEnvelopeMeta(meta).length === 0;
}

function classifyBatch(body: readonly unknown[]): InboundClassificationOutcome {
    if (body.length === 0) {
        return rejection(
            'jsonrpc-shape',
            'empty-batch',
            400,
            new ProtocolError(ProtocolErrorCode.InvalidRequest, 'Bad Request: empty JSON-RPC batch'),
            true
        );
    }
    for (const element of body) {
        const params = isPlainObject(element) ? element['params'] : undefined;
        if (hasEnvelopeClaim(params)) {
            // Element-wise rule: a single modern element makes the whole array
            // unservable — modern requests are single-message POSTs, and the
            // legacy path must never serve an envelope-claiming element.
            return rejection(
                'jsonrpc-shape',
                'batch-with-modern-element',
                400,
                new ProtocolError(
                    ProtocolErrorCode.InvalidRequest,
                    'Bad Request: JSON-RPC batches may not contain requests for protocol revision 2026-07-28 or later'
                ),
                true
            );
        }
        const valid =
            isJSONRPCRequest(element) ||
            isJSONRPCNotification(element) ||
            isJSONRPCResultResponse(element) ||
            isJSONRPCErrorResponse(element);
        if (!valid) {
            return rejection(
                'jsonrpc-shape',
                'batch-with-invalid-element',
                400,
                new ProtocolError(ProtocolErrorCode.InvalidRequest, 'Bad Request: JSON-RPC batch contains an invalid message'),
                true
            );
        }
    }
    // All elements are legacy-era messages: legacy serving takes the array unchanged.
    return { kind: 'legacy', reason: 'batch' };
}

function classifyRequestBody(request: InboundHttpRequest, body: JSONRPCRequest): InboundClassificationOutcome {
    const params = body.params;
    const method = body.method;
    const headerVersion = request.protocolVersionHeader;
    const headerNamesModern = headerVersion !== undefined && isModernProtocolVersion(headerVersion);

    // `initialize` is the legacy handshake by definition — unless the request
    // carries a valid envelope claim naming a modern revision, in which case
    // the claim wins: the request is classified like any other enveloped
    // request and served on the modern path, where the modern registry answers
    // `initialize` as method-not-found like every other method it does not
    // define. A malformed or absent claim, or a claim naming a pre-2026
    // revision, keeps the legacy-handshake classification below.
    if (method === 'initialize' && !carriesValidModernEnvelopeClaim(params)) {
        if (headerNamesModern) {
            return crossCheckMismatch(
                'initialize-with-modern-header',
                headerVersion,
                'an initialize request (legacy handshake) was sent with a modern MCP-Protocol-Version header'
            );
        }
        const requestedVersion =
            isPlainObject(params) && typeof params['protocolVersion'] === 'string' ? params['protocolVersion'] : undefined;
        return { kind: 'legacy', reason: 'initialize', ...(requestedVersion !== undefined && { requestedVersion }) };
    }

    if (hasEnvelopeClaim(params)) {
        // A present claim is validated, never silently ignored: a malformed
        // envelope behind the claim is an invalid-params rejection naming the
        // offending key, not a fall back to legacy handling.
        const meta = requestMetaOf(params);
        const issues = meta === undefined ? [] : validateEnvelopeMeta(meta);
        const firstIssue = issues[0];
        if (firstIssue !== undefined) {
            return rejection(
                'envelope',
                'envelope-invalid',
                400,
                new ProtocolError(
                    ProtocolErrorCode.InvalidParams,
                    `Invalid _meta envelope for protocol revision 2026-07-28: ${firstIssue.key}: ${firstIssue.problem}`,
                    { envelope: firstIssue }
                ),
                true
            );
        }

        const claimedVersion = envelopeClaimVersion(params);
        if (headerVersion !== undefined && claimedVersion !== undefined && headerVersion !== claimedVersion) {
            return crossCheckMismatch(
                'header-body-version-mismatch',
                headerVersion,
                `the body envelope names protocol version ${claimedVersion} but the MCP-Protocol-Version header names ${headerVersion}`
            );
        }
        if (request.mcpMethodHeader !== undefined && request.mcpMethodHeader !== method) {
            return crossCheckMismatch(
                'method-header-mismatch',
                request.mcpMethodHeader,
                `the body names method ${method} but the Mcp-Method header names ${request.mcpMethodHeader}`
            );
        }
        return { kind: 'modern', messageKind: 'request', message: body, classification: classificationForClaim(claimedVersion) };
    }

    // No claim: legacy-era traffic — unless the protocol-version header names a
    // modern revision. The modern revisions carry their request metadata in the
    // per-request `_meta` envelope, so a modern-classified request without one
    // is missing required params: it is rejected with invalid params naming the
    // missing key(s), never silently served as legacy traffic and never
    // upgraded from the header alone.
    if (headerNamesModern) {
        const meta = requestMetaOf(params);
        const missingFromEnvelope = validateEnvelopeMeta(meta ?? {})
            .filter(issue => issue.problem === 'missing')
            .map(issue => issue.key);
        const missing = meta === undefined ? ['_meta'] : missingFromEnvelope.length > 0 ? missingFromEnvelope : [PROTOCOL_VERSION_META_KEY];
        return rejection(
            'envelope',
            'modern-header-without-claim',
            400,
            new ProtocolError(
                ProtocolErrorCode.InvalidParams,
                `Invalid params: the MCP-Protocol-Version header names protocol revision ${headerVersion}, but the request is missing ` +
                    `the required per-request envelope key(s): ${missing.join(', ')}`,
                { envelope: { missing } }
            ),
            true
        );
    }
    return { kind: 'legacy', reason: 'no-claim', ...(headerVersion !== undefined && { requestedVersion: headerVersion }) };
}

function classifyNotificationBody(request: InboundHttpRequest, body: JSONRPCNotification): InboundClassificationOutcome {
    const params = body.params;
    const method = body.method;
    const headerVersion = request.protocolVersionHeader;
    const headerNamesModern = headerVersion !== undefined && isModernProtocolVersion(headerVersion);

    if (hasEnvelopeClaim(params)) {
        // Body-primary even for notifications: a body claim wins over the
        // header, and a disagreement between them is rejected rather than
        // letting either signal silently pick the serving path.
        const claimedVersion = envelopeClaimVersion(params);
        if (claimedVersion === undefined) {
            // The claim key is present but its value is malformed (not a
            // string). Validated exactly like a request claim: an
            // invalid-params rejection naming the offending key — never a
            // silent win against (or loss to) a disagreeing header.
            const meta = requestMetaOf(params);
            const issues = meta === undefined ? [] : validateEnvelopeMeta(meta);
            const claimIssue = issues.find(issue => issue.key === PROTOCOL_VERSION_META_KEY) ?? {
                key: PROTOCOL_VERSION_META_KEY,
                problem: 'expected a protocol version string'
            };
            return rejection(
                'envelope',
                'notification-envelope-invalid',
                400,
                new ProtocolError(
                    ProtocolErrorCode.InvalidParams,
                    `Invalid _meta envelope for protocol revision 2026-07-28: ${claimIssue.key}: ${claimIssue.problem}`,
                    { envelope: claimIssue }
                ),
                true
            );
        }
        if (headerVersion !== undefined && headerVersion !== claimedVersion) {
            return crossCheckMismatch(
                'notification-header-body-version-mismatch',
                headerVersion,
                `the notification envelope names protocol version ${claimedVersion} but the MCP-Protocol-Version header names ${headerVersion}`
            );
        }
        const classification = classificationForClaim(claimedVersion);
        if (classification.era === 'modern' && request.mcpMethodHeader !== undefined && request.mcpMethodHeader !== method) {
            return crossCheckMismatch(
                'notification-method-header-mismatch',
                request.mcpMethodHeader,
                `the notification body names method ${method} but the Mcp-Method header names ${request.mcpMethodHeader}`
            );
        }
        return { kind: 'modern', messageKind: 'notification', message: body, classification };
    }

    // Notifications carry no body claim under the current spec, so the
    // protocol-version header is determinative for them: a modern header
    // routes the notification to modern serving; a missing or legacy header
    // keeps it legacy traffic. The Mcp-Method header is validated only when
    // the notification classifies modern — it is never enforced on legacy
    // notifications.
    if (headerNamesModern) {
        if (request.mcpMethodHeader !== undefined && request.mcpMethodHeader !== method) {
            return crossCheckMismatch(
                'notification-method-header-mismatch',
                request.mcpMethodHeader,
                `the notification body names method ${method} but the Mcp-Method header names ${request.mcpMethodHeader}`
            );
        }
        return {
            kind: 'modern',
            messageKind: 'notification',
            message: body,
            classification: { era: 'modern', revision: headerVersion }
        };
    }
    return { kind: 'legacy', reason: 'notification', ...(headerVersion !== undefined && { requestedVersion: headerVersion }) };
}

/**
 * Classifies one inbound HTTP request for dual-era serving.
 *
 * The body-primary predicate, evaluated once at the entry boundary: see the
 * module documentation for the rules. Returns a routing outcome (`legacy` or
 * `modern`) or a ladder rejection; it never throws.
 */
export function classifyInboundRequest(request: InboundHttpRequest): InboundClassificationOutcome {
    // RFC 9110 §5.5: field parsing excludes optional whitespace around a
    // field value. Fetch implementations normally perform this normalization,
    // but transport-neutral callers and some runtimes can expose raw OWS.
    request = {
        ...request,
        ...(request.protocolVersionHeader !== undefined && {
            protocolVersionHeader: stripHttpOws(request.protocolVersionHeader)
        }),
        ...(request.mcpMethodHeader !== undefined && { mcpMethodHeader: stripHttpOws(request.mcpMethodHeader) }),
        ...(request.mcpNameHeader !== undefined && { mcpNameHeader: stripHttpOws(request.mcpNameHeader) })
    };

    if (request.httpMethod.toUpperCase() !== 'POST') {
        // Body-less 2025-era session operations (and any other non-POST
        // method): the modern era is POST-only.
        return { kind: 'legacy', reason: 'http-method' };
    }

    const body = request.body;
    if (Array.isArray(body)) {
        return classifyBatch(body);
    }
    if (isJSONRPCResultResponse(body) || isJSONRPCErrorResponse(body)) {
        // Posted responses are 2025-era session traffic (replies to
        // server-initiated requests over a session); the modern era has no
        // such channel.
        return { kind: 'legacy', reason: 'response' };
    }
    if (isPlainObject(body) && isJSONRPCRequest(body)) {
        return classifyRequestBody(request, body);
    }
    if (isPlainObject(body) && isJSONRPCNotification(body)) {
        return classifyNotificationBody(request, body);
    }
    return rejection(
        'jsonrpc-shape',
        'invalid-json-rpc-body',
        400,
        new ProtocolError(ProtocolErrorCode.InvalidRequest, 'Bad Request: the request body is not a valid JSON-RPC message'),
        true
    );
}

/* ------------------------------------------------------------------------ *
 * Modern-only (strict) mapping of legacy routes
 * ------------------------------------------------------------------------ */

/**
 * The rejection a modern-only endpoint (no legacy serving configured)
 * answers a legacy-classified request with.
 *
 * - Envelope-less requests (including `initialize`) are answered with the
 *   unsupported-protocol-version error carrying the endpoint's supported
 *   versions and echoing the version the request named (when it named one —
 *   `requested` is omitted rather than fabricated when the request named no
 *   version at all), so a legacy client can discover what the endpoint serves
 *   from the error alone.
 * - Posted responses and batch arrays are invalid requests on the modern era.
 * - Non-`POST` methods are not allowed.
 * - Legacy-classified notifications return `undefined`: the caller answers
 *   202 with no body and does not dispatch the notification (accept-and-drop).
 */
export function modernOnlyStrictRejection(
    route: InboundLegacyRoute,
    supportedVersions: readonly string[]
): InboundLadderRejection | undefined {
    switch (route.reason) {
        case 'http-method': {
            return rejection('http-method', 'modern-only-method-not-allowed', 405, new ProtocolError(-32_000, 'Method not allowed.'), true);
        }
        case 'batch': {
            return rejection(
                'jsonrpc-shape',
                'modern-only-batch-not-supported',
                400,
                new ProtocolError(ProtocolErrorCode.InvalidRequest, 'Bad Request: JSON-RPC batches are not supported by this endpoint'),
                true
            );
        }
        case 'response': {
            return rejection(
                'jsonrpc-shape',
                'modern-only-response-post',
                400,
                new ProtocolError(ProtocolErrorCode.InvalidRequest, 'Bad Request: JSON-RPC responses cannot be posted to this endpoint'),
                true
            );
        }
        case 'notification': {
            return undefined;
        }
        case 'initialize':
        case 'no-claim': {
            // `requested` reflects what the request actually named (an
            // initialize body's `protocolVersion` or the protocol-version
            // header); when the request named no version at all the field is
            // omitted rather than fabricated.
            const requested = route.requestedVersion;
            const error =
                requested === undefined
                    ? new ProtocolError(
                          ProtocolErrorCode.UnsupportedProtocolVersion,
                          'Unsupported protocol version: the request did not name a protocol version',
                          { supported: [...supportedVersions] }
                      )
                    : new UnsupportedProtocolVersionError({ supported: [...supportedVersions], requested });
            return rejection('era-classification', 'modern-only-missing-envelope', 400, error, true);
        }
    }
}
/**
 * Internal Zod schema utilities for protocol handling.
 * These are used internally by the SDK for protocol message validation.
 */

import * as z from 'zod/v4';

/**
 * Base type for any Zod schema.
 */
export type AnySchema = z.core.$ZodType;

/**
 * A Zod schema for objects specifically.
 */
export type AnyObjectSchema = z.core.$ZodObject;

/**
 * Extracts the output type from a Zod schema.
 */
export type SchemaOutput<T extends AnySchema> = z.output<T>;

/**
 * Parses data against a Zod schema (synchronous).
 * Returns a discriminated union with success/error.
 */
export function parseSchema<T extends AnySchema>(
    schema: T,
    data: unknown
): { success: true; data: z.output<T> } | { success: false; error: z.core.$ZodError } {
    return z.safeParse(schema, data);
}

/**
 * Union of the declared shape keys across several Zod object schemas.
 */
export function shapeKeys(schemas: Array<{ shape: Record<string, unknown> }>): ReadonlySet<string> {
    return new Set(schemas.flatMap(schema => Object.keys(schema.shape)));
}
/**
 * Standard Schema utilities for user-provided schemas.
 * Supports Zod v4, Valibot, ArkType, and other Standard Schema implementations.
 * @see https://standardschema.dev
 */

/* eslint-disable @typescript-eslint/no-namespace */

import * as z from 'zod/v4';

import type { StringSchema } from '../types/types';

// Standard Schema interfaces — vendored from https://standardschema.dev (spec v1, Jan 2025)

export interface StandardTypedV1<Input = unknown, Output = Input> {
    readonly '~standard': StandardTypedV1.Props<Input, Output>;
}

export namespace StandardTypedV1 {
    export interface Props<Input = unknown, Output = Input> {
        readonly version: 1;
        readonly vendor: string;
        readonly types?: Types<Input, Output> | undefined;
    }

    export interface Types<Input = unknown, Output = Input> {
        readonly input: Input;
        readonly output: Output;
    }

    export type InferInput<Schema extends StandardTypedV1> = NonNullable<Schema['~standard']['types']>['input'];
    export type InferOutput<Schema extends StandardTypedV1> = NonNullable<Schema['~standard']['types']>['output'];
}

export interface StandardSchemaV1<Input = unknown, Output = Input> {
    readonly '~standard': StandardSchemaV1.Props<Input, Output>;
}

export namespace StandardSchemaV1 {
    export interface Props<Input = unknown, Output = Input> extends StandardTypedV1.Props<Input, Output> {
        readonly validate: (value: unknown, options?: Options | undefined) => Result<Output> | Promise<Result<Output>>;
    }

    export interface Options {
        readonly libraryOptions?: Record<string, unknown> | undefined;
    }

    export type Result<Output> = SuccessResult<Output> | FailureResult;

    export interface SuccessResult<Output> {
        readonly value: Output;
        readonly issues?: undefined;
    }

    export interface FailureResult {
        readonly issues: ReadonlyArray<Issue>;
    }

    export interface Issue {
        readonly message: string;
        readonly path?: ReadonlyArray<PropertyKey | PathSegment> | undefined;
    }

    export interface PathSegment {
        readonly key: PropertyKey;
    }

    export type InferInput<Schema extends StandardTypedV1> = StandardTypedV1.InferInput<Schema>;
    export type InferOutput<Schema extends StandardTypedV1> = StandardTypedV1.InferOutput<Schema>;
}

export interface StandardJSONSchemaV1<Input = unknown, Output = Input> {
    readonly '~standard': StandardJSONSchemaV1.Props<Input, Output>;
}

export namespace StandardJSONSchemaV1 {
    export interface Props<Input = unknown, Output = Input> extends StandardTypedV1.Props<Input, Output> {
        readonly jsonSchema: Converter;
    }

    export interface Converter {
        readonly input: (options: Options) => Record<string, unknown>;
        readonly output: (options: Options) => Record<string, unknown>;
    }

    export type Target = 'draft-2020-12' | 'draft-07' | 'openapi-3.0' | (object & string);

    export interface Options {
        readonly target: Target;
        readonly libraryOptions?: Record<string, unknown> | undefined;
    }

    export type InferInput<Schema extends StandardTypedV1> = StandardTypedV1.InferInput<Schema>;
    export type InferOutput<Schema extends StandardTypedV1> = StandardTypedV1.InferOutput<Schema>;
}

/**
 * Combined interface for schemas with both validation and JSON Schema conversion —
 * the intersection of {@linkcode StandardSchemaV1} and {@linkcode StandardJSONSchemaV1}.
 *
 * This is the type accepted by `registerTool` / `registerPrompt`. The SDK needs
 * `~standard.jsonSchema` to advertise the tool's argument shape in `tools/list`, and
 * `~standard.validate` to check incoming arguments when a `tools/call` arrives.
 *
 * Zod v4, ArkType, and Valibot (via `@valibot/to-json-schema`'s `toStandardJsonSchema`)
 * all implement both interfaces.
 *
 * @see https://standardschema.dev/ for the Standard Schema specification
 */
export interface StandardSchemaWithJSON<Input = unknown, Output = Input> {
    readonly '~standard': StandardSchemaV1.Props<Input, Output> & StandardJSONSchemaV1.Props<Input, Output>;
}

export namespace StandardSchemaWithJSON {
    export type InferInput<Schema extends StandardTypedV1> = StandardTypedV1.InferInput<Schema>;
    export type InferOutput<Schema extends StandardTypedV1> = StandardTypedV1.InferOutput<Schema>;
}

/**
 * Narrowing of {@linkcode StandardSchemaV1} whose `validate` is guaranteed synchronous.
 *
 * The Zod schemas backing `specTypeSchemas` contain no async refinements or transforms,
 * so every entry satisfies this interface. Consumers can call `validate()` and access
 * `.issues` / `.value` on the result without `await`.
 *
 * `StandardSchemaV1Sync` is assignable to `StandardSchemaV1` — it is a strict subtype.
 */
export interface StandardSchemaV1Sync<Input = unknown, Output = Input> extends StandardSchemaV1<Input, Output> {
    readonly '~standard': StandardSchemaV1Sync.Props<Input, Output>;
}

export namespace StandardSchemaV1Sync {
    export interface Props<Input = unknown, Output = Input> extends StandardSchemaV1.Props<Input, Output> {
        readonly validate: (value: unknown, options?: StandardSchemaV1.Options | undefined) => StandardSchemaV1.Result<Output>;
    }

    export type InferInput<Schema extends StandardTypedV1> = StandardTypedV1.InferInput<Schema>;
    export type InferOutput<Schema extends StandardTypedV1> = StandardTypedV1.InferOutput<Schema>;
}

// Type guards

export function isStandardJSONSchema(schema: unknown): schema is StandardJSONSchemaV1 {
    if (schema == null) return false;
    const schemaType = typeof schema;
    if (schemaType !== 'object' && schemaType !== 'function') return false;
    if (!('~standard' in (schema as object))) return false;
    const std = (schema as StandardJSONSchemaV1)['~standard'];
    return typeof std?.jsonSchema?.input === 'function' && typeof std?.jsonSchema?.output === 'function';
}

export function isStandardSchema(schema: unknown): schema is StandardSchemaV1 {
    if (schema == null) return false;
    const schemaType = typeof schema;
    if (schemaType !== 'object' && schemaType !== 'function') return false;
    if (!('~standard' in (schema as object))) return false;
    const std = (schema as StandardSchemaV1)['~standard'];
    return typeof std?.validate === 'function';
}

export function isStandardSchemaWithJSON(schema: unknown): schema is StandardSchemaWithJSON {
    return isStandardJSONSchema(schema) && isStandardSchema(schema);
}

// JSON Schema conversion

let warnedZodFallback = false;

/** JSON Schema draft targeted by every conversion; shared so pattern references above stay in lockstep. */
export const JSON_SCHEMA_CONVERSION_TARGET = 'draft-2020-12';

/**
 * Converts a StandardSchema to JSON Schema for use as an MCP tool/prompt schema.
 *
 * MCP requires `type: "object"` at the root of tool `inputSchema` and prompt
 * argument schemas; `outputSchema` may have any JSON Schema root (SEP-2106).
 * Zod's discriminated unions emit `{oneOf: [...]}` without a top-level `type`,
 * so for `io: 'input'` this function defaults `type` to `"object"` when absent
 * and throws on an explicit non-object `type` (e.g. `z.string()`). For
 * `io: 'output'` a non-object root is returned as-is; the `"object"` default is
 * applied only when the root is provably object-shaped.
 */
export function standardSchemaToJsonSchema(schema: StandardJSONSchemaV1, io: 'input' | 'output' = 'input'): Record<string, unknown> {
    const std = schema['~standard'];
    let result: Record<string, unknown>;
    if (std.jsonSchema) {
        result = std.jsonSchema[io]({ target: JSON_SCHEMA_CONVERSION_TARGET });
    } else if (std.vendor === 'zod') {
        // zod 4.0–4.1 implements StandardSchemaV1 but not StandardJSONSchemaV1 (`~standard.jsonSchema`).
        // The SDK already bundles zod 4, so fall back to its converter rather than crashing on tools/list.
        // zod 3 schemas (which also report vendor 'zod') have `_def` but not `_zod`; the SDK-bundled
        // zod 4 `z.toJSONSchema()` cannot introspect them, so throw a clear error instead of crashing.
        if (!('_zod' in (schema as object))) {
            throw new Error(
                'Schema appears to be from zod 3, which the SDK cannot convert to JSON Schema. ' +
                    'Upgrade to zod >=4.2.0, or wrap your JSON Schema with fromJsonSchema().'
            );
        }
        if (!warnedZodFallback) {
            warnedZodFallback = true;
            console.warn(
                '[mcp-sdk] Your zod version does not implement `~standard.jsonSchema` (added in zod 4.2.0). ' +
                    'Falling back to z.toJSONSchema(). Upgrade to zod >=4.2.0 to silence this warning.'
            );
        }
        result = z.toJSONSchema(schema as unknown as z.ZodType, { target: JSON_SCHEMA_CONVERSION_TARGET, io }) as Record<string, unknown>;
    } else {
        throw new Error(
            `Schema library "${std.vendor}" does not implement StandardJSONSchemaV1 (\`~standard.jsonSchema\`). ` +
                `Upgrade to a version that does, or wrap your JSON Schema with fromJsonSchema().`
        );
    }
    if (io === 'output') {
        // SEP-2106: outputSchema may have any JSON Schema root. An explicit `type` (object or
        // not) is returned as-is. A typeless root only gets `type:'object'` defaulted when it is
        // PROVABLY object-shaped — either it carries object keywords at the root, or every
        // member of a root `oneOf`/`anyOf`/`allOf` is itself `type:'object'` (the
        // `z.discriminatedUnion(...)`, `z.union([z.object(...), ...])`, `z.intersection(...)`
        // cases). Those pre-SEP schemas were valid 2025 wire data via the unconditional stamp,
        // so the stamp is kept where it is provably safe. A typeless root that is NOT provably
        // object-shaped (e.g. `z.union([z.string(), z.number()])` → `{anyOf:[…]}`) is returned
        // as-is — stamping there would be self-contradictory. Anything that does not end up
        // `type:'object'` is wrapped as `{type:'object', properties:{result:…}}` by the 2025
        // codec's legacy projection (see `wire/rev2025-11-25/legacyWrap.ts`).
        if (result.type !== undefined) return result;
        return isProvablyObjectShapedRoot(result) ? { type: 'object', ...result } : result;
    }
    if (result.type !== undefined && result.type !== 'object') {
        throw new Error(
            `MCP tool and prompt schemas must describe objects (got type: ${JSON.stringify(result.type)}). ` +
                `Wrap your schema in z.object({...}) or equivalent.`
        );
    }
    return { type: 'object', ...result };
}

/**
 * A typeless JSON Schema root is "provably object-shaped" when either it carries object keywords
 * directly (`properties`/`patternProperties`/`additionalProperties`/`required`), or it is a
 * composition (`oneOf`/`anyOf`/`allOf`) whose every member is itself `type:'object'` or recursively
 * provably object-shaped (e.g. a nested `discriminatedUnion`). `$ref` is not followed. Used to
 * decide whether stamping `type:'object'` is safe (redundant-but-valid) versus self-contradictory.
 */
function isProvablyObjectShapedRoot(schema: Record<string, unknown>): boolean {
    if ('properties' in schema || 'patternProperties' in schema || 'additionalProperties' in schema || 'required' in schema) {
        return true;
    }
    for (const key of ['oneOf', 'anyOf', 'allOf'] as const) {
        const members = schema[key];
        if (Array.isArray(members) && members.length > 0) {
            return members.every(
                m =>
                    m !== null &&
                    typeof m === 'object' &&
                    ((m as Record<string, unknown>).type === 'object' || isProvablyObjectShapedRoot(m as Record<string, unknown>))
            );
        }
    }
    return false;
}

// Validation

export type StandardSchemaValidationResult<T> = { success: true; data: T } | { success: false; error: string };

function formatIssue(issue: StandardSchemaV1.Issue): string {
    if (!issue.path?.length) return issue.message;
    const path = issue.path.map(p => String(typeof p === 'object' ? p.key : p)).join('.');
    return `${path}: ${issue.message}`;
}

export async function validateStandardSchema<T extends StandardSchemaV1>(
    schema: T,
    data: unknown
): Promise<StandardSchemaValidationResult<StandardSchemaV1.InferOutput<T>>> {
    const result = await schema['~standard'].validate(data);
    if (result.issues && result.issues.length > 0) {
        return { success: false, error: result.issues.map(i => formatIssue(i)).join(', ') };
    }
    return { success: true, data: (result as StandardSchemaV1.SuccessResult<unknown>).value as StandardSchemaV1.InferOutput<T> };
}

/*
 * Format-companion patterns: libraries realize a string `format` check as a companion
 * `pattern` regex, which the elicitation wire schema cannot carry. zod's are derived
 * from the resolved zod at runtime (never vendored — in-range releases change them), so
 * customized zod patterns are distinguishable and reject; other vendors' realizations
 * are unknowable (e.g. ArkType's `string.email`), so their patterns are trusted-and-dropped.
 */

function zodEmittedPattern(schema: z.ZodType): string | undefined {
    const jsonSchema = z.toJSONSchema(schema, { target: JSON_SCHEMA_CONVERSION_TARGET, io: 'input' }) as Record<string, unknown>;
    return typeof jsonSchema.pattern === 'string' ? jsonSchema.pattern : undefined;
}

const DATETIME_FRACTION_DIGITS = /\\\.\\d\{(\d+)\}/;

function datetimeReferenceSchemas(pattern: string): z.ZodType[] {
    // Options (offset/local/precision) vary the emission; recovering the fraction-digit
    // count keeps the candidate set finite.
    const fractionDigits = DATETIME_FRACTION_DIGITS.exec(pattern);
    const precisions: Array<number | undefined> = [undefined, -1, 0];
    if (fractionDigits) {
        precisions.push(Number(fractionDigits[1]));
    }
    return [false, true].flatMap(local =>
        [false, true].flatMap(offset => precisions.map(precision => z.iso.datetime({ local, offset, precision })))
    );
}

// Exhaustive over the wire's format enum: a new spec format is a compile error here.
function referencePatternsForFormat(format: NonNullable<StringSchema['format']>, pattern: string): ReadonlySet<string> {
    let referenceSchemas: z.ZodType[];
    switch (format) {
        case 'email': {
            referenceSchemas = [z.email()];
            break;
        }
        case 'uri': {
            referenceSchemas = [z.url()];
            break;
        }
        case 'date': {
            referenceSchemas = [z.iso.date()];
            break;
        }
        case 'date-time': {
            referenceSchemas = datetimeReferenceSchemas(pattern);
            break;
        }
    }
    return new Set(referenceSchemas.map(schema => zodEmittedPattern(schema)).filter((emitted): emitted is string => emitted !== undefined));
}

/** Whether `pattern` is the library's own realization of `format` (droppable) rather than a user customization. */
export function isLibraryFormatPattern(format: NonNullable<StringSchema['format']>, pattern: string, vendor: string): boolean {
    if (vendor !== 'zod') {
        return true;
    }
    return referencePatternsForFormat(format, pattern).has(pattern);
}

// Prompt argument extraction

export function promptArgumentsFromStandardSchema(
    schema: StandardJSONSchemaV1
): Array<{ name: string; description?: string; required: boolean }> {
    const jsonSchema = standardSchemaToJsonSchema(schema, 'input');
    const properties = (jsonSchema.properties as Record<string, { description?: string }>) || {};
    const required = (jsonSchema.required as string[]) || [];

    return Object.entries(properties).map(([name, prop]) => ({
        name,
        description: prop?.description,
        required: required.includes(name)
    }));
}
import { ProtocolErrorCode } from '../types/enums';
import { ProtocolError } from '../types/errors';
import {
    BooleanSchemaSchema,
    ElicitRequestFormParamsSchema,
    LegacyTitledEnumSchemaSchema,
    NumberSchemaSchema,
    PrimitiveSchemaDefinitionSchema,
    StringSchemaSchema,
    TitledMultiSelectEnumSchemaSchema,
    TitledSingleSelectEnumSchemaSchema,
    UntitledMultiSelectEnumSchemaSchema,
    UntitledSingleSelectEnumSchemaSchema
} from '../types/schemas';
import type { ElicitRequestFormParams, StringSchema } from '../types/types';
import { parseSchema, shapeKeys } from '../util/schema';
import type { StandardSchemaWithJSON } from '../util/standardSchema';
import { isLibraryFormatPattern, isStandardSchema, standardSchemaToJsonSchema } from '../util/standardSchema';

/** Input accepted by `inputRequired.elicit()`: a wire-ready elicitation JSON Schema or a Standard Schema. */
export type ElicitInputParams = Omit<ElicitRequestFormParams, 'requestedSchema'> & {
    requestedSchema: ElicitRequestFormParams['requestedSchema'] | StandardSchemaWithJSON;
};

function isJsonObject(value: unknown): value is Record<string, unknown> {
    return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function convertStandardElicitationSchema(schema: StandardSchemaWithJSON): Record<string, unknown> {
    try {
        return standardSchemaToJsonSchema(schema, 'input');
    } catch (error) {
        const detail = error instanceof Error ? error.message : String(error);
        throw new ProtocolError(
            ProtocolErrorCode.InvalidParams,
            `Elicitation requestedSchema must describe an object with flat primitive properties: ${detail}`
        );
    }
}

// JSON Schema metadata-vocabulary keys: positions that cannot carry them drop them silently.
const ANNOTATION_ONLY_JSON_SCHEMA_KEYWORDS = new Set([
    '$comment',
    'deprecated',
    'description',
    'examples',
    'readOnly',
    'title',
    'writeOnly'
]);

function isAnnotationOnlyJsonSchemaKeyword(key: string): boolean {
    return ANNOTATION_ONLY_JSON_SCHEMA_KEYWORDS.has(key) || key.startsWith('x-');
}

// The wire grammar, derived from the wire schemas so it tracks spec revisions. `$schema`
// is spec-declared on the root but reaches the wire type via its catchall.
const ROOT_KEYS = new Set(['$schema', ...Object.keys(ElicitRequestFormParamsSchema.shape.requestedSchema.shape)]);

const PROPERTY_KEYS_BY_TYPE: Record<string, ReadonlySet<string>> = {
    string: shapeKeys([
        StringSchemaSchema,
        UntitledSingleSelectEnumSchemaSchema,
        TitledSingleSelectEnumSchemaSchema,
        LegacyTitledEnumSchemaSchema
    ]),
    number: shapeKeys([NumberSchemaSchema]),
    integer: shapeKeys([NumberSchemaSchema]),
    boolean: shapeKeys([BooleanSchemaSchema]),
    array: shapeKeys([UntitledMultiSelectEnumSchemaSchema, TitledMultiSelectEnumSchemaSchema])
};

const SUPPORTED_STRING_FORMATS: ReadonlySet<string> = new Set(StringSchemaSchema.shape.format.unwrap().options);

/** Walks one property node: keeps grammar keys, drops the library format pattern, rejects unknown constraints. */
function walkProperty(node: unknown, path: string, vendor: string, unsupported: string[]): unknown {
    if (!isJsonObject(node)) {
        return node;
    }
    // Object.hasOwn: a `type` like 'constructor' must not resolve through the prototype chain.
    const allowedKeys =
        typeof node.type === 'string' && Object.hasOwn(PROPERTY_KEYS_BY_TYPE, node.type) ? PROPERTY_KEYS_BY_TYPE[node.type] : undefined;
    if (allowedKeys === undefined) {
        // Unknown `type` — value validation rejects the node and names it.
        return node;
    }

    const pruned: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(node)) {
        if (allowedKeys.has(key) || isAnnotationOnlyJsonSchemaKeyword(key)) {
            pruned[key] = value;
        } else if (key === 'pattern' && node.type === 'string' && typeof node.format === 'string') {
            if (!SUPPORTED_STRING_FORMATS.has(node.format)) {
                pruned[key] = value; // the unsupported format itself fails value validation
            } else if (
                typeof value !== 'string' ||
                !isLibraryFormatPattern(node.format as NonNullable<StringSchema['format']>, value, vendor)
            ) {
                // A customized pattern must not be silently weakened.
                unsupported.push(`${path}.${key}`);
            }
        } else {
            unsupported.push(`${path}.${key}`);
        }
    }
    return pruned;
}

/** Walks the schema root: keeps the spec root keys, drops annotations, rejects the rest. */
function walkRequestedSchema(converted: Record<string, unknown>, vendor: string): Record<string, unknown> {
    const pruned: Record<string, unknown> = {};
    const unsupported: string[] = [];
    for (const [key, value] of Object.entries(converted)) {
        if (key === 'properties' && isJsonObject(value)) {
            pruned[key] = Object.fromEntries(
                Object.entries(value).map(([name, node]) => [name, walkProperty(node, `properties.${name}`, vendor, unsupported)])
            );
        } else if (ROOT_KEYS.has(key)) {
            pruned[key] = value;
        } else if (!isAnnotationOnlyJsonSchemaKeyword(key)) {
            unsupported.push(key);
        }
    }
    if (unsupported.length > 0) {
        throw new ProtocolError(
            ProtocolErrorCode.InvalidParams,
            `Elicitation requestedSchema contains unsupported JSON Schema constraint(s) after Standard Schema conversion: ${unsupported.join(', ')}`
        );
    }
    return pruned;
}

/** Names the properties that fail value validation, instead of surfacing a raw union dump. */
function describeUnsupportedProperties(pruned: Record<string, unknown>, fallback: string): string {
    if (!isJsonObject(pruned.properties)) {
        return fallback;
    }
    const offenders = Object.entries(pruned.properties)
        .filter(([, node]) => !parseSchema(PrimitiveSchemaDefinitionSchema, node).success)
        .map(([name]) => `properties.${name}`);
    return offenders.length > 0 ? offenders.join(', ') : fallback;
}

// Safety net: value validation strips key combinations no single wire shape carries
// (e.g. `format` beside `enum`); a dropped non-annotation key must reject.
function findDroppedConstraintPaths(original: unknown, parsed: unknown, path = ''): string[] {
    if (Array.isArray(original) && Array.isArray(parsed)) {
        return original.flatMap((item, index) => findDroppedConstraintPaths(item, parsed[index], `${path}[${index}]`));
    }
    if (!isJsonObject(original) || !isJsonObject(parsed)) {
        return [];
    }
    return Object.entries(original).flatMap(([key, value]) => {
        const childPath = path ? `${path}.${key}` : key;
        if (!Object.prototype.hasOwnProperty.call(parsed, key)) {
            return isAnnotationOnlyJsonSchemaKeyword(key) ? [] : [childPath];
        }
        return findDroppedConstraintPaths(value, parsed[key], childPath);
    });
}

/** Converts an authoring-friendly elicitation input into its wire-ready form. */
export function normalizeElicitInputParams(input: ElicitInputParams): ElicitRequestFormParams {
    // Route on `~standard.validate`: the converter owns the per-vendor fallback (zod
    // 4.0/4.1 has no `~standard.jsonSchema`) — same decision as normalizeRawShapeSchema.
    if (!isStandardSchema(input.requestedSchema)) {
        return { ...input, mode: 'form', requestedSchema: input.requestedSchema };
    }

    const vendor = input.requestedSchema['~standard'].vendor;
    const pruned = walkRequestedSchema(convertStandardElicitationSchema(input.requestedSchema), vendor);

    // Scoped to the converted schema so params-level fields behave as on the raw branch.
    const parsed = parseSchema(ElicitRequestFormParamsSchema.shape.requestedSchema, pruned);
    if (!parsed.success) {
        throw new ProtocolError(
            ProtocolErrorCode.InvalidParams,
            `Elicitation requestedSchema only supports flat primitive properties (string, number, integer, boolean, and string enums): ${describeUnsupportedProperties(pruned, parsed.error.message)}`
        );
    }

    const droppedConstraints = findDroppedConstraintPaths(pruned, parsed.data);
    if (droppedConstraints.length > 0) {
        throw new ProtocolError(
            ProtocolErrorCode.InvalidParams,
            `Elicitation requestedSchema contains unsupported JSON Schema constraint(s) after Standard Schema conversion: ${droppedConstraints.join(', ')}`
        );
    }

    // Converters can lose exotic property names from `properties` while keeping them in
    // `required` (zod's toJSONSchema does for `__proto__`).
    const danglingRequired = (parsed.data.required ?? []).filter(key => !Object.prototype.hasOwnProperty.call(parsed.data.properties, key));
    if (danglingRequired.length > 0) {
        throw new ProtocolError(
            ProtocolErrorCode.InvalidParams,
            `Elicitation requestedSchema lists required properties that are not defined in properties: ${danglingRequired.join(', ')}`
        );
    }

    return { ...input, mode: 'form', requestedSchema: parsed.data };
}
/**
 * Authoring helpers for multi-round-trip requests (protocol revision
 * 2026-07-28).
 *
 * A handler for one of the multi-round-trip methods (`tools/call`,
 * `prompts/get`, `resources/read`) requests additional client input by
 * returning an {@linkcode InputRequiredResult} instead of a final result. The
 * helpers here build that return value and its embedded requests as NEUTRAL
 * values; only the 2026-07-28 wire codec maps them to/from the wire. The
 * 2025-era codec has no input-required vocabulary — on a 2025-era request the
 * server's legacy shim (on by default) fulfils the embedded requests as real
 * server→client requests and re-enters the handler, so the same return shape
 * serves both eras; `ServerOptions.inputRequired.legacyShim: false` restores
 * the pre-shim loud failure.
 *
 * There is no nominal brand: `resultType: 'input_required'` is the
 * discriminator, and hand-built result literals are equally legal — the
 * server seam re-checks the at-least-one rule for them.
 */
import { ProtocolError } from '../types/errors';
import { isInputRequiredResult } from '../types/guards';
import type {
    CreateMessageRequestParams,
    CreateMessageResult,
    CreateMessageResultWithTools,
    ElicitRequestURLParams,
    InputRequest,
    InputRequests,
    InputRequiredResult,
    InputResponses,
    Root
} from '../types/types';
import type { StandardSchemaV1 } from '../util/standardSchema';
import type { ElicitInputParams } from './elicitation';
import { normalizeElicitInputParams } from './elicitation';

export type { ElicitInputParams } from './elicitation';

/** The shape accepted by {@linkcode inputRequired}. */
export interface InputRequiredSpec {
    /** Embedded requests the client must fulfil before retrying. */
    inputRequests?: InputRequests;
    /** Opaque server state echoed back verbatim by the client on retry. */
    requestState?: string;
}

interface InputRequiredBuilder {
    /**
     * Builds the input-required return value for a multi-round-trip handler.
     *
     * At least one of `inputRequests` or `requestState` must be provided
     * (spec: basic/patterns/mrtr, server requirements) — the builder throws a
     * `TypeError` otherwise, and the server seam re-checks the same rule for
     * hand-built results.
     *
     * `requestState` is opaque, server-minted state. It round-trips through
     * the client and comes back as attacker-controlled input: a server that
     * lets it influence authorization, resource access, or business logic
     * MUST integrity-protect it (e.g. HMAC or AEAD) and MUST reject state
     * that fails verification. The SDK does not do this for you.
     */
    (spec: InputRequiredSpec): InputRequiredResult;

    /**
     * Builds an embedded form-mode elicitation request (`elicitation/create`).
     *
     * A Standard Schema `requestedSchema` is converted to the restricted wire shape;
     * shapes it cannot express throw a `TypeError` before anything is sent. Responses
     * are not validated against it — pass the same schema to `acceptedContent()` on
     * re-entry for validated, typed content.
     */
    elicit(params: ElicitInputParams): InputRequest;

    /**
     * Builds an embedded URL-mode elicitation request (`elicitation/create`).
     * On the 2026-07-28 revision URL elicitation rides the multi-round-trip
     * flow — the `-32042` error of earlier revisions never appears on this
     * era's wire. The 2025-era `elicitationId` is not part of the 2026-07-28
     * URL-mode shape; correlation across retries is the server's own
     * identifier inside `requestState`.
     */
    elicitUrl(params: Omit<ElicitRequestURLParams, 'mode' | 'elicitationId'>): InputRequest;

    /** Builds an embedded sampling request (`sampling/createMessage`). */
    createMessage(params: CreateMessageRequestParams): InputRequest;

    /** Builds an embedded roots listing request (`roots/list`). */
    listRoots(): InputRequest;
}

function buildInputRequired(spec: InputRequiredSpec): InputRequiredResult {
    const hasInputRequests = spec.inputRequests !== undefined && Object.keys(spec.inputRequests).length > 0;
    const hasRequestState = typeof spec.requestState === 'string';
    if (!hasInputRequests && !hasRequestState) {
        throw new TypeError(
            'inputRequired() requires at least one of inputRequests (with at least one entry) or requestState ' +
                '(spec: every InputRequiredResult MUST include at least one of the two)'
        );
    }
    return {
        resultType: 'input_required',
        ...(spec.inputRequests !== undefined && { inputRequests: spec.inputRequests }),
        ...(spec.requestState !== undefined && { requestState: spec.requestState })
    };
}

/**
 * Builder for the input-required return value of multi-round-trip handlers,
 * with per-kind constructors for the embedded requests
 * (`inputRequired.elicit`, `inputRequired.elicitUrl`,
 * `inputRequired.createMessage`, `inputRequired.listRoots`).
 *
 * @example Write-once tool requesting confirmation
 * ```ts
 * server.registerTool('deploy', { inputSchema: z.object({ env: z.string() }) }, async ({ env }, ctx) => {
 *     const confirmed = acceptedContent<{ confirm: boolean }>(ctx.mcpReq.inputResponses, 'confirm');
 *     if (!confirmed) {
 *         return inputRequired({
 *             inputRequests: {
 *                 confirm: inputRequired.elicit({
 *                     message: `Deploy to ${env}?`,
 *                     requestedSchema: { type: 'object', properties: { confirm: { type: 'boolean' } }, required: ['confirm'] }
 *                 })
 *             }
 *         });
 *     }
 *     return { content: [{ type: 'text', text: `deployed to ${env}` }] };
 * });
 * ```
 */
export const inputRequired: InputRequiredBuilder = Object.assign(buildInputRequired, {
    elicit(params: ElicitInputParams): InputRequest {
        try {
            return { method: 'elicitation/create', params: normalizeElicitInputParams(params) };
        } catch (error) {
            throw error instanceof ProtocolError ? new TypeError(error.message, { cause: error }) : error;
        }
    },
    elicitUrl(params: Omit<ElicitRequestURLParams, 'mode' | 'elicitationId'>): InputRequest {
        // The neutral ElicitRequestURLParams keeps `elicitationId` (it is required on the
        // frozen 2025-11-25 revision); the 2026-07-28 in-band shape does not carry it.
        return { method: 'elicitation/create', params: { ...params, mode: 'url' } as ElicitRequestURLParams };
    },
    createMessage(params: CreateMessageRequestParams): InputRequest {
        return { method: 'sampling/createMessage', params };
    },
    listRoots(): InputRequest {
        return { method: 'roots/list' };
    }
});

/**
 * Reads the accepted content of a form-mode elicitation response from a
 * retried request's `inputResponses` (`ctx.mcpReq.inputResponses`).
 *
 * Returns the response's `content` for `key` when the entry is an accepted
 * elicitation result, and `undefined` otherwise (missing key, declined or
 * cancelled elicitation, or a response of another kind). The values arrive
 * from the client and are not re-validated here — treat them as untrusted
 * input.
 */
export function acceptedContent<T extends Record<string, unknown> = Record<string, unknown>>(
    responses: InputResponses | Record<string, unknown> | undefined,
    key: string
): T | undefined;

/**
 * Schema-aware overload: validates the accepted content against the given
 * schema (any Standard Schema, e.g. a zod object) before returning it, so the
 * untrusted client value arrives in the handler already validated and typed.
 *
 * Returns `undefined` when the response is missing/declined/of another kind
 * (as the two-argument form does) AND when the accepted content fails schema
 * validation — handlers treat both the same way (re-issue the request or
 * give up). Only synchronous schemas are supported (zod schemas without async
 * refinements are synchronous); an asynchronously-validating schema throws a
 * `TypeError`.
 */
export function acceptedContent<S extends StandardSchemaV1>(
    responses: InputResponses | Record<string, unknown> | undefined,
    key: string,
    schema: S
): StandardSchemaV1.InferOutput<S> | undefined;

export function acceptedContent(
    responses: InputResponses | Record<string, unknown> | undefined,
    key: string,
    schema?: StandardSchemaV1
): unknown {
    const view = inputResponse(responses, key);
    if (view.kind !== 'elicit' || view.action !== 'accept' || view.content === undefined) return undefined;
    if (schema === undefined) return view.content;
    const outcome = schema['~standard'].validate(view.content);
    if (outcome instanceof Promise) {
        throw new TypeError('acceptedContent(responses, key, schema) requires a synchronously-validating schema');
    }
    return outcome.issues === undefined ? outcome.value : undefined;
}

/**
 * The discriminated view {@linkcode inputResponse} returns: which kind of
 * embedded response (if any) a retried request carried for a key. Bare
 * response objects are discriminated structurally — an `action` member means
 * an elicitation result, a `roots` array a roots listing, a `role` + `content`
 * pair a sampling result. A missing key or an entry that matches none of the
 * three shapes reads as `{ kind: 'missing' }`.
 */
export type InputResponseView =
    | { kind: 'missing' }
    | { kind: 'elicit'; action: 'accept' | 'decline' | 'cancel'; content?: Record<string, unknown> }
    | { kind: 'sampling'; result: CreateMessageResult | CreateMessageResultWithTools }
    | { kind: 'roots'; roots: Root[] };

/**
 * Reads one entry of a retried request's `inputResponses`
 * (`ctx.mcpReq.inputResponses`) as a discriminated view, covering
 * decline/cancel detection and the non-elicitation response kinds that
 * {@linkcode acceptedContent} does not surface.
 *
 * The values arrive from the client and are not re-validated here — treat
 * them as untrusted input (validate elicitation content with the
 * schema-aware {@linkcode acceptedContent} overload where it matters).
 */
export function inputResponse(responses: InputResponses | Record<string, unknown> | undefined, key: string): InputResponseView {
    if (responses === undefined || typeof responses !== 'object' || responses === null) return { kind: 'missing' };
    const entry = (responses as Record<string, unknown>)[key];
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) return { kind: 'missing' };
    const candidate = entry as Record<string, unknown>;
    if (candidate['action'] === 'accept' || candidate['action'] === 'decline' || candidate['action'] === 'cancel') {
        const content = candidate['content'];
        return {
            kind: 'elicit',
            action: candidate['action'],
            ...(content !== null &&
                typeof content === 'object' &&
                !Array.isArray(content) && { content: content as Record<string, unknown> })
        };
    }
    if (Array.isArray(candidate['roots'])) {
        return { kind: 'roots', roots: candidate['roots'] as Root[] };
    }
    if (typeof candidate['role'] === 'string' && candidate['content'] !== undefined) {
        return { kind: 'sampling', result: candidate as unknown as CreateMessageResult | CreateMessageResultWithTools };
    }
    return { kind: 'missing' };
}

/**
 * Wraps a result schema so a request issued through `client.request()` /
 * `ctx.mcpReq.send()` with `allowInputRequired: true` is typed as either the
 * schema's result or an {@linkcode InputRequiredResult}.
 *
 * The manual multi-round-trip path: pass `{ allowInputRequired: true }` in the
 * request options so an `input_required` response is handed back to the
 * caller instead of being auto-fulfilled (or rejected), and wrap the result
 * schema with `withInputRequired()` so the returned value is typed and
 * validated correctly for both outcomes — `input_required` values pass
 * through as-is, complete results validate against the wrapped schema.
 */
export function withInputRequired<S extends StandardSchemaV1>(
    schema: S
): StandardSchemaV1<unknown, StandardSchemaV1.InferOutput<S> | InputRequiredResult> {
    return {
        '~standard': {
            version: 1,
            vendor: 'modelcontextprotocol',
            validate: (value: unknown, options?: StandardSchemaV1.Options) => {
